635	    moves,
636	    times,
637	    minZ,
638	    maxZ,
639	    maxR,
640	    minC,
641	    maxC,
642	    extrudingCount,
643	    lineStats,
644	    generator,
645	    printer,
646	    nonPlanar,
647	    bedCenter: usedCenter,
648	    conversion,
649	    offPlate: { moves: Uint32Array.from(offPlateMoves), traits: offPlateTraits },
650	    markers: {
651	      retraction: Uint32Array.from(retractionAt),
652	      unretraction: Uint32Array.from(unretractionAt),
653	      seam: Uint32Array.from(seamAt),
654	    },
655	  };
656	}
657	
658	/** Temps machine (s) à l'index de mouvement fractionnaire `t`. */
659	export function timeAtIndex(times: Float64Array, t: number) {
660	  const last = times.length - 1;
661	  const i = Math.max(0, Math.min(last, Math.floor(t)));
662	  if (i >= last) return times[last];
663	  return times[i] + (times[i + 1] - times[i]) * (t - i);
664	}
665	
666	/** Index de mouvement fractionnaire atteint au temps machine `s` (inverse de `timeAtIndex`). */
667	export function indexAtTime(times: Float64Array, s: number) {
668	  const last = times.length - 1;
669	  if (s <= 0) return 0;
670	  if (s >= times[last]) return last;
671	  let lo = 0, hi = last; // times[lo] <= s < times[hi]
672	  while (hi - lo > 1) {
673	    const mid = (lo + hi) >> 1;
674	    if (times[mid] <= s) lo = mid; else hi = mid;
675	  }
676	  return lo + (s - times[lo]) / (times[hi] - times[lo]);
677	}
678	
679	/** Position machine (x, y, z, b) interpolée linéairement — comme le firmware — au temps `t`
680	 * exprimé en index de mouvement fractionnaire. */
681	export function stateAt(moves: GCodeMove[], t: number) {
682	  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
683	  const a = moves[i];
684	  const b = moves[Math.min(moves.length - 1, i + 1)];
685	  const f = Math.max(0, Math.min(1, t - i));
686	  return {
687	    x: a.x + (b.x - a.x) * f,
688	    y: a.y + (b.y - a.y) * f,
689	    z: a.z + (b.z - a.z) * f,
690	    b: a.b + (b.b - a.b) * f,
691	  };
692	}
693	
694	/**
695	 * Échantillonnage de la trajectoire en repère plateau (Babylon : y vers le haut) : position de la
696	 * pointe de buse et axe de la buse à la fraction `f` du mouvement `k`, et nombre de sous-segments
697	 * de chaque mouvement (subdivision angulaire en polaire, segment droit en cartésien).
698	 */
699	interface PathSampler {
700	  segments: Uint32Array;
701	  tip(k: number, f: number, out: BABYLON.Vector3): void;
702	  axis(k: number, f: number, out: BABYLON.Vector3): void;
703	}
704	
705	function createSampler(parsed: ParsedGCode): PathSampler {
706	  const { moves } = parsed;
707	  const segments = new Uint32Array(moves.length);
708	  const from = (k: number) => moves[k > 0 ? k - 1 : 0];
709	
710	  if (parsed.kind === 'cartesian') {
711	    segments.fill(1);
712	    return {
713	      segments,
714	      tip(k, f, out) {
715	        const a = from(k), m = moves[k];
716	        out.set(a.x + (m.x - a.x) * f, a.z + (m.z - a.z) * f, a.y + (m.y - a.y) * f);
717	      },
718	      axis(_k, _f, out) {
719	        out.set(0, 1, 0);
720	      },
721	    };
722	  }
723	
724	  for (let k = 1; k < moves.length; k++) {
725	    const dc = Math.abs(moves[k].y - moves[k - 1].y);
726	    segments[k] = Math.max(1, Math.ceil(dc / MAX_SUBSEGMENT_DEG));
727	  }
728	  const tipRZ = { r: 0, z: 0 };
729	  return {
730	    segments,
731	    // Interpolation en coordonnées pivot (comme le firmware), puis conversion à la buse.
732	    tip(k, f, out) {
733	      const a = from(k), m = moves[k];
734	      const c = (a.y + (m.y - a.y) * f) * DEG2RAD;
735	      nozzleTip(a.x + (m.x - a.x) * f, a.z + (m.z - a.z) * f, (a.b + (m.b - a.b) * f) * DEG2RAD, tipRZ);
736	      out.set(tipRZ.r * Math.cos(c), tipRZ.z, tipRZ.r * Math.sin(c));
737	    },
738	    // Axe de buse (vers le haut de la tête) : (sin B, cos B) dans le demi-plan machine, dont la
739	    // direction radiale est à l'angle C du dépôt.
740	    axis(k, f, out) {
741	      const a = from(k), m = moves[k];
742	      const c = (a.y + (m.y - a.y) * f) * DEG2RAD;
743	      const b = (a.b + (m.b - a.b) * f) * DEG2RAD;
744	      out.set(Math.sin(b) * Math.cos(c), Math.cos(b), Math.sin(b) * Math.sin(c));
745	    },
746	  };
747	}
748	
749	interface PathMesh {
750	  mesh: BABYLON.Mesh | null;
751	  /** Nombre d'indices à dessiner une fois le mouvement k terminé. */
752	  cumIndices: Uint32Array;
753	  /** Nombre d'indices par sous-segment : granularité de l'affichage d'un mouvement partiel. */
754	  indicesPerStep: number;
755	}
756	
757	/** Section du cordon déposé (mm) : largeur de part et d'autre de la trajectoire, et épaisseur le
758	 * long de l'axe de la buse. Valeurs nominales (pas de largeur/hauteur de couche lue). */
759	export const BEAD_WIDTH_MM = 0.6;
760	export const BEAD_HEIGHT_MM = 0.3;
761	/** Nombre de facettes de la section du cordon. */
762	const TUBE_SIDES = 6;
763	/** Diamètre des sphères des marqueurs ponctuels (rétractions, coutures). */
764	const MARKER_DIAMETER_MM = 0.8;
765	
766	const RING_COS = Float32Array.from({ length: TUBE_SIDES }, (_, i) => Math.cos((i / TUBE_SIDES) * Math.PI * 2));
767	const RING_SIN = Float32Array.from({ length: TUBE_SIDES }, (_, i) => Math.sin((i / TUBE_SIDES) * Math.PI * 2));
768	
769	/**
770	 * Écrit l'anneau n° `ring` du cordon (TUBE_SIDES sommets et normales) : ellipse centrée en c,
771	 * perpendiculaire à la tangente unitaire t, écrasée le long de l'axe de buse a (BEAD_HEIGHT_MM)
772	 * et large de BEAD_WIDTH_MM sur le côté.
773	 */
774	function writeRing(
775	  positions: Float32Array,
776	  normals: Float32Array,
777	  ring: number,
778	  cx: number, cy: number, cz: number,
779	  tx: number, ty: number, tz: number,
780	  ax: number, ay: number, az: number,
781	) {
782	  const halfW = BEAD_WIDTH_MM / 2;
783	  const halfH = BEAD_HEIGHT_MM / 2;
784	  // Axe de buse rendu orthogonal à la tangente ; s'il lui est parallèle (déplacement le long
785	  // de la buse), n'importe quelle perpendiculaire convient.
786	  let ux = ax, uy = ay, uz = az;
787	  const dot = ux * tx + uy * ty + uz * tz;
788	  ux -= dot * tx; uy -= dot * ty; uz -= dot * tz;
789	  let len = Math.hypot(ux, uy, uz);
790	  if (len < 1e-6) {
791	    ux = -ty; uy = tx; uz = 0;
792	    len = Math.hypot(ux, uy, uz);
793	    if (len < 1e-6) { ux = 0; uy = -tz; uz = ty; len = Math.hypot(uy, uz); }
794	  }
795	  ux /= len; uy /= len; uz /= len;
796	  // Côté = tangente × axe.
797	  const sx = ty * uz - tz * uy;
798	  const sy = tz * ux - tx * uz;
799	  const sz = tx * uy - ty * ux;
800	
801	  for (let i = 0; i < TUBE_SIDES; i++) {
802	    const v = (ring * TUBE_SIDES + i) * 3;
803	    const cs = RING_COS[i], sn = RING_SIN[i];
804	    positions[v] = cx + sx * halfW * cs + ux * halfH * sn;
805	    positions[v + 1] = cy + sy * halfW * cs + uy * halfH * sn;
806	    positions[v + 2] = cz + sz * halfW * cs + uz * halfH * sn;
807	    // Normale d'ellipse : gradient (cos/a, sin/b) dans le repère (côté, axe).
808	    let nx = sx * cs / halfW + ux * sn / halfH;
809	    let ny = sy * cs / halfW + uy * sn / halfH;
810	    let nz = sz * cs / halfW + uz * sn / halfH;
811	    const nl = Math.hypot(nx, ny, nz) || 1;
812	    nx /= nl; ny /= nl; nz /= nl;
813	    normals[v] = nx;
814	    normals[v + 1] = ny;
815	    normals[v + 2] = nz;
816	  }
817	}
818	
819	/** Donne à un sous-maillage affiché par préfixe (`indexCount`) une boîte englobante propre. */
820	function finalizePathMesh(mesh: BABYLON.Mesh) {
821	  // Tant que `indexCount` couvre toute la géométrie, Babylon traite le sous-maillage comme
822	  // « global » et lui prête la boîte englobante du maillage ; dès qu'on n'en affiche qu'un
823	  // préfixe, il lit sa boîte propre — jamais créée, d'où un crash dans le tri des objets
824	  // transparents qui arrêtait la boucle de rendu. On lui en donne une une fois pour toutes :
825	  // celle de la trajectoire complète, qui englobe n'importe quel préfixe (pas de
826	  // `refreshBoundingInfo`, qui reparcourrait les indices à chaque rotation du plateau).
827	  const { minimum, maximum } = mesh.getBoundingInfo();
828	  mesh.subMeshes[0].setBoundingInfo(new BABYLON.BoundingInfo(minimum.clone(), maximum.clone()));
829	  mesh.isPickable = false;
830	  mesh.alwaysSelectAsActiveMesh = true;
831	}
832	
833	/**
834	 * Construit le cordon de matière (repère plateau) : un tube à section elliptique le long des
835	 * mouvements retenus par `include`, dans l'ordre du fichier. La section est orientée selon l'axe
836	 * de la buse au moment du dépôt (écrasée le long de cet axe, BEAD_HEIGHT_MM) et centrée une
837	 * demi-épaisseur sous la pointe de buse, là où la matière est réellement posée. Les mouvements
838	 * retenus consécutifs partagent leurs anneaux de jonction : un seul tube continu par suite
839	 * ininterrompue. N'importe quel préfixe s'affiche en changeant `indexCount`, sans reconstruire.
840	 */
841	function buildBeadMesh(
842	  name: string,
843	  parsed: ParsedGCode,
844	  sampler: PathSampler,
845	  include: (k: number) => boolean,
846	  material: BABYLON.Material,
847	  scene: BABYLON.Scene,
848	): PathMesh {
849	  const { moves } = parsed;
850	  const { segments } = sampler;
851	  const indicesPerStep = TUBE_SIDES * 6;
852	  const cumIndices = new Uint32Array(moves.length);
853	
854	  let capacity = 0;
855	  for (let k = 1; k < moves.length; k++) {
856	    if (include(k)) capacity += segments[k] + 1;
857	  }
858	  if (capacity === 0) return { mesh: null, cumIndices, indicesPerStep };
859	
860	  // Passe 1 : échantillons le long de la trajectoire — centre du cordon, axe de buse, mouvement
861	  // propriétaire et début de tube (pas de sous-segment qui le relie au précédent).
862	  const centers = new Float32Array(capacity * 3);
863	  const axes = new Float32Array(capacity * 3);
864	  const owner = new Uint32Array(capacity);
865	  const stripStart = new Uint8Array(capacity);
866	  const tip = new BABYLON.Vector3();
867	  const ax = new BABYLON.Vector3();
868	  const halfH = BEAD_HEIGHT_MM / 2;
869	  let count = 0;
870	
871	  for (let k = 1; k < moves.length; k++) {
872	    if (!include(k)) continue;
873	    // Le mouvement précédent était déjà dans ce cordon : son dernier échantillon est notre point
874	    // de départ, on prolonge le même tube au lieu d'en ouvrir un nouveau.
875	    const continues = k > 1 && include(k - 1);
876	    const n = segments[k];
877	    for (let s = continues ? 1 : 0; s <= n; s++) {
878	      const f = s / n;
879	      sampler.tip(k, f, tip);
880	      sampler.axis(k, f, ax);
881	      centers[count * 3] = tip.x - ax.x * halfH;
882	      centers[count * 3 + 1] = tip.y - ax.y * halfH;
883	      centers[count * 3 + 2] = tip.z - ax.z * halfH;
884	      axes[count * 3] = ax.x;
885	      axes[count * 3 + 1] = ax.y;
886	      axes[count * 3 + 2] = ax.z;
887	      owner[count] = k;
888	      stripStart[count] = s === 0 ? 1 : 0;
889	      count++;
890	    }
891	  }
892	
893	  // Passe 2 : un anneau elliptique par échantillon, dans le repère (côté, axe de buse)
894	  // perpendiculaire à la tangente, puis les quads entre anneaux consécutifs d'un même tube.
895	  const positions = new Float32Array(count * TUBE_SIDES * 3);
896	  const normals = new Float32Array(count * TUBE_SIDES * 3);
897	  const indices = new Uint32Array(count * indicesPerStep);
898	  // Dernière tangente valide : reprise pour les échantillons confondus, dont la tangente locale
899	  // est nulle.
900	  let tx = 1, ty = 0, tz = 0;
901	  let idx = 0;
902	
903	  for (let j = 0; j < count; j++) {
904	    const p = j * 3;
905	    const hasPrev = !stripStart[j];
906	    const hasNext = j + 1 < count && !stripStart[j + 1];
907	    const from = hasPrev ? p - 3 : p;
908	    const to = hasNext ? p + 3 : p;
909	    const dx = centers[to] - centers[from];
910	    const dy = centers[to + 1] - centers[from + 1];
911	    const dz = centers[to + 2] - centers[from + 2];
912	    const len = Math.hypot(dx, dy, dz);
913	    if (len > 1e-6) {
914	      tx = dx / len; ty = dy / len; tz = dz / len;
915	    }
916	    writeRing(positions, normals, j, centers[p], centers[p + 1], centers[p + 2], tx, ty, tz, axes[p], axes[p + 1], axes[p + 2]);
917	
918	    if (hasPrev) {
919	      const a0 = (j - 1) * TUBE_SIDES;
920	      const b0 = j * TUBE_SIDES;
921	      for (let i = 0; i < TUBE_SIDES; i++) {
922	        const i1 = (i + 1) % TUBE_SIDES;
923	        indices[idx++] = a0 + i;
924	        indices[idx++] = b0 + i;
925	        indices[idx++] = a0 + i1;
926	        indices[idx++] = a0 + i1;
927	        indices[idx++] = b0 + i;
928	        indices[idx++] = b0 + i1;
929	      }
930	      cumIndices[owner[j]] = idx;
931	    }
932	  }
933	  // Mouvements hors de ce cordon : même compte que le précédent.
934	  for (let k = 1; k < moves.length; k++) {
935	    if (cumIndices[k] < cumIndices[k - 1]) cumIndices[k] = cumIndices[k - 1];
936	  }
937	
938	  const mesh = new BABYLON.Mesh(name, scene);
939	  const data = new BABYLON.VertexData();
940	  data.positions = positions;
941	  data.normals = normals;
942	  data.indices = indices.subarray(0, idx);
943	  data.applyToMesh(mesh);
944	  mesh.material = material;
945	  finalizePathMesh(mesh);
946	  return { mesh, cumIndices, indicesPerStep };
947	}
948	
949	/** Construit un LinesMesh (repère plateau) des mouvements retenus par `include`, dans l'ordre du
950	 * fichier. N'importe quel préfixe s'affiche ensuite en changeant `indexCount`. */
951	function buildPathMesh(
952	  name: string,
953	  parsed: ParsedGCode,
954	  sampler: PathSampler,
955	  include: (k: number) => boolean,
956	  color: BABYLON.Color3,
957	  scene: BABYLON.Scene,
958	): PathMesh {
959	  const { moves } = parsed;
960	  const { segments } = sampler;
961	  let vertexTotal = 0;
962	  for (let k = 1; k < moves.length; k++) {
963	    if (include(k)) vertexTotal += segments[k] + 1;
964	  }
965	
966	  const cumIndices = new Uint32Array(moves.length);
967	  if (vertexTotal === 0) return { mesh: null, cumIndices, indicesPerStep: 2 };
968	
969	  const positions = new Float32Array(vertexTotal * 3);
970	  const indices = new Uint32Array((vertexTotal - 1) * 2);
971	  const tip = new BABYLON.Vector3();
972	  let v = 0;
973	  let idx = 0;
974	
975	  for (let k = 1; k < moves.length; k++) {
976	    if (include(k)) {
977	      const n = segments[k];
978	      for (let s = 0; s <= n; s++) {
979	        sampler.tip(k, s / n, tip);
980	        positions[v * 3] = tip.x;
981	        positions[v * 3 + 1] = tip.y;
982	        positions[v * 3 + 2] = tip.z;
983	        if (s > 0) {
984	          indices[idx++] = v - 1;
985	          indices[idx++] = v;
986	        }
987	        v++;
988	      }
989	    }
990	    cumIndices[k] = idx;
991	  }
992	
993	  const mesh = new BABYLON.LinesMesh(name, scene);
994	  const data = new BABYLON.VertexData();
995	  data.positions = positions;
996	  data.indices = indices.subarray(0, idx);
997	  data.applyToMesh(mesh);
998	  mesh.color = color;
999	  mesh.alpha = 0.85;
1000	  finalizePathMesh(mesh);
1001	  return { mesh, cumIndices, indicesPerStep: 2 };
1002	}
1003	
1004	/** Sphères (instances légères) aux positions de fin des mouvements `at`. */
1005	function buildMarkerMesh(
1006	  name: string,
1007	  at: Uint32Array,
1008	  sampler: PathSampler,
1009	  color: BABYLON.Color3,
1010	  scene: BABYLON.Scene,
1011	) {
1012	  if (!at.length) return null;
1013	  const mesh = BABYLON.MeshBuilder.CreateSphere(name, { diameter: MARKER_DIAMETER_MM, segments: 6 }, scene);
1014	  const material = new BABYLON.StandardMaterial(`${name}Mat`, scene);
1015	  material.disableLighting = true;
1016	  material.emissiveColor = color;
1017	  mesh.material = material;
1018	  const matrices = new Float32Array(at.length * 16);
1019	  const p = new BABYLON.Vector3();
1020	  const m = new BABYLON.Matrix();
1021	  for (let j = 0; j < at.length; j++) {
1022	    sampler.tip(at[j], 1, p);
1023	    BABYLON.Matrix.TranslationToRef(p.x, p.y, p.z, m);
1024	    m.copyToArray(matrices, j * 16);
1025	  }
1026	  mesh.thinInstanceSetBuffer('matrix', matrices, 16, true);
1027	  mesh.isPickable = false;
1028	  mesh.alwaysSelectAsActiveMesh = true;
1029	  return mesh;
1030	}
1031	
1032	/** Nombre d'éléments de `sorted` (croissant) inférieurs ou égaux à `t`. */
1033	function countUpTo(sorted: Uint32Array, t: number) {
1034	  let lo = 0, hi = sorted.length;
1035	  while (lo < hi) {
1036	    const mid = (lo + hi) >> 1;
1037	    if (sorted[mid] <= t) lo = mid + 1; else hi = mid;
1038	  }
1039	  return lo;
1040	}
1041	
1042	export interface GCodeLayer {
1043	  load(parsed: ParsedGCode): void;
1044	  /** Position de lecture, en index de mouvement fractionnaire. */
1045	  setTime(t: number): void;
1046	  /** Types de ligne affichés (cf. `apex-gcode-line-visibility`). */
1047	  setLineTypeVisibility(visibility: LineTypeVisibility): void;
1048	  /** Surligne en rouge les traits hors plateau (cf. `apex-gcode-highlight-offplate`). */
1049	  setOffPlateHighlight(show: boolean): void;
1050	  /** Tête complète (défaut) ou buse seule — masque tous les maillages de la tête sauf ceux nommés
1051	   * « NOZZLE » (cf. `apex-gcode-show-full-head`). */

