1	import { useCallback, useEffect, useRef, useState } from 'react';
2	import { showError, showSuccess, showWarning } from '@/utils/toast';
3	import {
4	  parseGCode,
5	  stateAt,
6	  timeAtIndex,
7	  indexAtTime,
8	  SUSPICIOUS_C_RANGE_DEG,
9	  PLATE_RADIUS_MM,
10	  type ParsedGCode,
11	  type GCodeKind,
12	  type LineTypeStat,
13	  type ConversionMode,
14	} from '@/components/gcodeLayer';
15	import { DEFAULT_LINE_VISIBILITY, type LineTypeId, type LineTypeVisibility } from '@/components/gcodeLineTypes';
16	import type { GCodeGenerator } from '@/components/gcodeGenerator';
17	import { isConversionAvailable, runConversion } from '@/utils/gcodeConversion';
18	
19	/**
20	 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
21	 * la fenêtre ou sélecteur), horloge de lecture et affichage des trajets à vide. Le rendu 3D est
22	 * fait par Viewport3D, piloté par les événements :
23	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
24	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
25	 *  - `apex-gcode-line-visibility` { visibility } : types de ligne affichés (cf. gcodeLineTypes.ts).
26	 */
27	
28	// Multiplicateurs du temps machine réel (1 = vitesse d'impression réelle, avances F du fichier).
29	export const GCODE_SPEED_OPTIONS = [0.01, 1, 4, 16, 64, 256];
30	export const GCODE_ACCEPT = '.gcode,.gco,.g,.ngc';
31	/** Reconnaît un nom de fichier G-code par son extension — exporté pour Sidebar.tsx (bascule
32	 * automatique vers l'espace Prévisualisation au dépôt d'un tel fichier en Préparation). */
33	export const GCODE_FILE_EXT = /\.(gcode|gco|g|ngc)$/i;
34	
35	export interface GCodeFileInfo {
36	  name: string;
37	  kind: GCodeKind;
38	  lineStats: Record<LineTypeId, LineTypeStat>;
39	  /** Temps machine total (s). */
40	  totalTime: number;
41	  generator: GCodeGenerator | null;
42	  printer: string | null;
43	  /** 3 axes à Z variable dans les couches : l'angle dynamique est recommandé pour la conversion. */
44	  nonPlanar: boolean;
45	  /** Fichier issu de la conversion polaire d'Apex (mode), sinon null. */
46	  conversion: ConversionMode | null;
47	  moves: number;
48	  extruding: number;
49	  minZ: number;
50	  maxZ: number;
51	  minC: number;
52	  maxC: number;
53	}
54	
55	export interface ConversionState {
56	  status: 'idle' | 'running' | 'done' | 'error';
57	  /** Avancement 0–100 pendant la conversion. */
58	  progress: number;
59	  /** Mode demandé (en cours) ou obtenu (terminé). */
60	  mode: ConversionMode | null;
61	  error: string | null;
62	}
63	
64	const IDLE_CONVERSION: ConversionState = { status: 'idle', progress: 0, mode: null, error: null };
65	
66	/** Surlignage rouge, dans le viewport, des traits hors plateau de la source 3 axes affichée. */
67	const setOffPlateHighlight = (show: boolean) =>
68	  window.dispatchEvent(new CustomEvent('apex-gcode-highlight-offplate', { detail: { show } }));
69	
70	const dispatchTime = (t: number) =>
71	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
72	
73	/** @param active Espace Prévisualisation affiché (active le dépôt de fichier, coupe la lecture sinon). */
74	export function useGCodePreview(active: boolean) {
75	  const parsedRef = useRef<ParsedGCode | null>(null);
76	  const tRef = useRef(0);
77	  const dragDepthRef = useRef(0);
78	
79	  const [fileInfo, setFileInfo] = useState<GCodeFileInfo | null>(null);
80	  const [t, setT] = useState(0);
81	  const [isPlaying, setIsPlaying] = useState(false);
82	  const [speed, setSpeed] = useState(GCODE_SPEED_OPTIONS[1]);
83	  const [lineVisibility, setLineVisibility] = useState<LineTypeVisibility>(DEFAULT_LINE_VISIBILITY);
84	  const [showFullHead, setShowFullHead] = useState(true);
85	  const [isDragging, setIsDragging] = useState(false);
86	  // Le temps de lire le fichier et de parser son texte (`loadFile`, ci-dessous) : permet à
87	  // GCodePreviewBar de s'afficher dès le début du chargement plutôt que d'attendre `fileInfo`.
88	  const [isLoading, setIsLoading] = useState(false);
89	  // Fichier 3 axes chargé par l'utilisateur (source de la conversion polaire, gardée après
90	  // conversion pour reconvertir dans l'autre mode) et G-code actuellement affiché (celui exporté).
91	  const sourceRef = useRef<{ text: string; name: string; parsed: ParsedGCode } | null>(null);
92	  const currentRef = useRef<{ text: string; name: string } | null>(null);
93	  const [conversion, setConversion] = useState<ConversionState>(IDLE_CONVERSION);
94	
95	  useEffect(() => {
96	    if (!active) setIsPlaying(false);
97	  }, [active]);
98	
99	  useEffect(() => {
100	    window.dispatchEvent(new CustomEvent('apex-gcode-line-visibility', { detail: { visibility: lineVisibility } }));
101	  }, [lineVisibility]);
102	
103	  // Stable : la légende (mémoïsée) ne doit pas se redessiner à chaque rafraîchissement de lecture.
104	  const setLineVisible = useCallback((id: LineTypeId, visible: boolean) =>
105	    setLineVisibility((prev) => ({ ...prev, [id]: visible })), []);
106	
107	  useEffect(() => {
108	    window.dispatchEvent(new CustomEvent('apex-gcode-show-full-head', { detail: { show: showFullHead } }));
109	  }, [showFullHead]);
110	
111	  // Horloge de lecture : avance le temps machine (durées réelles des mouvements, cf.
112	  // `ParsedGCode.times`) à `speed` × le temps réel, le reconvertit en index de mouvement `t`,
113	  // pousse chaque image au viewport et rafraîchit l'état React à ~20 Hz seulement.
114	  useEffect(() => {
115	    if (!isPlaying) return;
116	    const parsed = parsedRef.current;
117	    if (!parsed) return;
118	    const last = parsed.moves.length - 1;
119	    let raf = 0;
120	    let prev = performance.now();
121	    let sinceUiSync = 0;
122	    const step = (now: number) => {
123	      const dt = (now - prev) / 1000;
124	      prev = now;
125	      const s = timeAtIndex(parsed.times, tRef.current) + speed * dt;
126	      tRef.current = Math.min(last, indexAtTime(parsed.times, s));
127	      dispatchTime(tRef.current);
128	      sinceUiSync += dt;
129	      if (tRef.current >= last) {
130	        setT(last);
131	        setIsPlaying(false);
132	        return;
133	      }
134	      if (sinceUiSync > 1 / 20) {
135	        sinceUiSync = 0;
136	        setT(tRef.current);
137	      }
138	      raf = requestAnimationFrame(step);
139	    };
140	    raf = requestAnimationFrame(step);
141	    return () => cancelAnimationFrame(raf);
142	  }, [isPlaying, speed]);
143	
144	  /** Parse et affiche un G-code ; renvoie le résultat, ou null (erreur déjà signalée). */
145	  const loadText = (text: string, name: string): ParsedGCode | null => {
146	    let parsed: ParsedGCode;
147	    try {
148	      parsed = parseGCode(text);
149	    } catch {
150	      showError('Impossible de lire ce fichier G-code.');
151	      return null;
152	    }
153	    if (parsed.moves.length < 2) {
154	      showError('Aucune trajectoire exploitable dans ce fichier.');
155	      return null;
156	    }
157	
158	    parsedRef.current = parsed;
159	    currentRef.current = { text, name };
160	    const last = parsed.moves.length - 1;
161	    tRef.current = last;
162	    setIsPlaying(false);
163	    setT(last);
164	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
165	
166	    setFileInfo({
167	      name,
168	      kind: parsed.kind,
169	      lineStats: parsed.lineStats,
170	      totalTime: parsed.times[parsed.times.length - 1],
171	      generator: parsed.generator,
172	      printer: parsed.printer,
173	      nonPlanar: parsed.nonPlanar,
174	      conversion: parsed.conversion,
175	      moves: parsed.moves.length,
176	      extruding: parsed.extrudingCount,
177	      minZ: parsed.minZ,
178	      maxZ: parsed.maxZ,
179	      minC: parsed.minC,
180	      maxC: parsed.maxC,
181	    });
182	    return parsed;
183	  };
184	
185	  const loadFile = async (file: File) => {
186	    if (!GCODE_FILE_EXT.test(file.name)) {
187	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
188	      return;
189	    }
190	    setIsLoading(true);
191	    const text = await file.text().catch(() => null);
192	    const parsed = text === null ? null : loadText(text, file.name);
193	    setIsLoading(false);
194	    if (!parsed) return;
195	
196	    // Nouveau fichier : il devient la source d'une éventuelle conversion polaire (s'il est 3 axes).
197	    sourceRef.current = parsed.kind === 'cartesian'
198	      ? { text: text!, name: file.name, parsed }
199	      : null;
200	    setConversion(IDLE_CONVERSION);
201	    setOffPlateHighlight(false);
202	
203	    // Un C qui accumule les tours est normal dans un fichier converti (le plateau suit la pièce).
204	    if (parsed.kind === 'polar' && !parsed.conversion && parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
205	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
206	    } else {
207	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
208	    }
209	  };
210	
211	  /** Convertit la source 3 axes en G-code polaire Apex (script Python de l'application de bureau)
212	   * et affiche le résultat ; la source est conservée pour reconvertir dans l'autre mode. */
213	  const convert = async (mode: ConversionMode, dropOffPlate: boolean) => {
214	    const source = sourceRef.current;
215	    if (!source || conversion.status === 'running') return;
216	    setOffPlateHighlight(false);
217	    setConversion({ status: 'running', progress: 0, mode, error: null });
218	    try {
219	      const { text, summary } = await runConversion(
220	        {
221	          text: source.text,
222	          mode,
223	          centerX: source.parsed.bedCenter.x,
224	          centerY: source.parsed.bedCenter.y,
225	          source: source.parsed.generator?.name ?? source.name,
226	          dropOutsideRadius: dropOffPlate ? PLATE_RADIUS_MM : 0,
227	        },
228	        (progress) => setConversion((prev) => (prev.status === 'running' ? { ...prev, progress } : prev)),
229	      );
230	      const name = `${source.name.replace(/\.[^.]+$/, '')}_apex${mode === 'dynamic' ? '_dynamique' : ''}.gcode`;
231	      if (!loadText(text, name)) throw new Error('Le G-code converti est illisible.');
232	      setConversion({ status: 'done', progress: 100, mode, error: null });
233	      const detail = summary
234	        ? ` (écart max ${summary.maxErrorMm.toFixed(3).replace('.', ',')} mm${mode === 'dynamic' ? `, B de ${summary.bMin.toFixed(0)}° à ${summary.bMax.toFixed(0)}°` : ''}${summary.droppedMoves ? `, ${summary.droppedMoves} mouvements hors plateau supprimés` : ''})`
235	        : '';
236	      showSuccess(`G-code converti en polaire${mode === 'dynamic' ? ' à angle dynamique' : ''}${detail}.`);
237	    } catch (err) {
238	      const message = err instanceof Error ? err.message.replace(/^Error invoking remote method '[^']+': (Error: )?/, '') : String(err);
239	      setConversion({ status: 'error', progress: 0, mode, error: message });
240	      showError(`Conversion impossible : ${message}`);
241	    }
242	  };
243	
244	  /** Enregistre le G-code affiché (boîte d'enregistrement native, ou téléchargement hors application). */
245	  const exportGCode = async () => {
246	    const current = currentRef.current;
247	    if (!current) return;
248	    try {
249	      if (window.apexDesktop) {
250	        const result = await window.apexDesktop.saveGCode(current);
251	        if (result.saved) showSuccess(`G-code exporté : ${result.path}`);
252	        return;
253	      }
254	      const url = URL.createObjectURL(new Blob([current.text], { type: 'text/plain' }));
255	      const link = document.createElement('a');
256	      link.href = url;
257	      link.download = current.name;
258	      link.click();
259	      setTimeout(() => URL.revokeObjectURL(url), 0);
260	    } catch (err) {
261	      showError(`Export impossible : ${err instanceof Error ? err.message : String(err)}`);
262	    }
263	  };
264	
265	  // Fichier reçu de Sidebar.tsx (dépôt en Préparation, cf. `enterPreview`) une fois la bascule
266	  // animée vers l'espace Prévisualisation terminée — dispatché seulement APRÈS
267	  // `apex-preview-toggled { active: true }`, donc toujours reçu ici avec `active` déjà vrai.
268	  // `loadFileRef` : la fonction est recréée à chaque rendu (elle ferme sur `file`, capturé par
269	  // paramètre, pas par un état qui changerait), mais l'effet ne doit s'abonner qu'une fois — sans
