271	  // seuls des setters stables (jamais lus depuis une valeur figée) sont appelés à l'intérieur.
272	  const loadFileRef = useRef(loadFile);
273	  loadFileRef.current = loadFile;
274	  useEffect(() => {
275	    const onEnteringPreviewWithFile = (e: Event) => {
276	      const file = (e as CustomEvent<{ file: File }>).detail?.file;
277	      if (file) loadFileRef.current(file);
278	    };
279	    window.addEventListener('apex-entering-preview-with-file', onEnteringPreviewWithFile);
280	    return () => window.removeEventListener('apex-entering-preview-with-file', onEnteringPreviewWithFile);
281	  }, []);
282	
283	  /** Ouvre le sélecteur de fichier système (sans élément `<input>` dans l'interface). */
284	  const openFilePicker = () => {
285	    const input = document.createElement('input');
286	    input.type = 'file';
287	    input.accept = GCODE_ACCEPT;
288	    input.onchange = () => {
289	      const file = input.files?.[0];
290	      if (file) loadFile(file);
291	    };
292	    input.click();
293	  };
294	
295	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
296	  // souris pour la caméra, aucun élément d'interface n'a donc besoin de capter le dépôt.
297	  useEffect(() => {
298	    if (!active) return;
299	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
300	    const onDragEnter = (e: DragEvent) => {
301	      if (!hasFiles(e)) return;
302	      e.preventDefault();
303	      dragDepthRef.current++;
304	      setIsDragging(true);
305	    };
306	    const onDragOver = (e: DragEvent) => {
307	      if (!hasFiles(e)) return;
308	      e.preventDefault();
309	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
310	    };
311	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
312	    const onDragLeave = (e: DragEvent) => {
313	      if (!hasFiles(e)) return;
314	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
315	      if (dragDepthRef.current === 0) setIsDragging(false);
316	    };
317	    const onDrop = (e: DragEvent) => {
318	      if (!hasFiles(e)) return;
319	      e.preventDefault();
320	      dragDepthRef.current = 0;
321	      setIsDragging(false);
322	      const file = e.dataTransfer?.files?.[0];
323	      if (file) loadFileRef.current(file);
324	    };
325	    window.addEventListener('dragenter', onDragEnter);
326	    window.addEventListener('dragover', onDragOver);
327	    window.addEventListener('dragleave', onDragLeave);
328	    window.addEventListener('drop', onDrop);
329	    return () => {
330	      window.removeEventListener('dragenter', onDragEnter);
331	      window.removeEventListener('dragover', onDragOver);
332	      window.removeEventListener('dragleave', onDragLeave);
333	      window.removeEventListener('drop', onDrop);
334	      dragDepthRef.current = 0;
335	      setIsDragging(false);
336	    };
337	  }, [active]);
338	
339	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
340	  // Viewport mis à jour immédiatement ; l'état React (qui redessine toute la page) au plus une fois
341	  // par image, pour qu'un glisser envoyant plusieurs événements par image reste fluide.
342	  const seekSyncRafRef = useRef(0);
343	  const seek = (value: number) => {
344	    setIsPlaying(false);
345	    tRef.current = value;
346	    dispatchTime(value);
347	    if (seekSyncRafRef.current) return;
348	    seekSyncRafRef.current = requestAnimationFrame(() => {
349	      seekSyncRafRef.current = 0;
350	      setT(tRef.current);
351	    });
352	  };
353	
354	  /** Lecture/pause ; repart du début si la lecture est au bout. */
355	  const togglePlay = () => {
356	    const parsed = parsedRef.current;
357	    if (!parsed) return;
358	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
359	    setIsPlaying(!isPlaying);
360	  };
361	
362	  const parsed = parsedRef.current;
363	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
364	  const current = parsed ? stateAt(parsed.moves, t) : null;
365	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
366	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
367	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
368	
369	  return {
370	    fileInfo,
371	    t,
372	    lastIndex,
373	    current,
374	    currentMove,
375	    isPlaying,
376	    togglePlay,
377	    seek,
378	    speed,
379	    setSpeed,
380	    lineVisibility,
381	    setLineVisible,
382	    showFullHead,
383	    setShowFullHead,
384	    isDragging,
385	    isLoading,
386	    loadFile,
387	    openFilePicker,
388	    conversion,
389	    /** G-code 3 axes chargé, convertible en polaire (qu'il l'ait déjà été ou non), sinon null. */
390	    conversionSource: fileInfo && sourceRef.current
391	      ? {
392	        name: sourceRef.current.name,
393	        nonPlanar: sourceRef.current.parsed.nonPlanar,
394	        offPlateTraits: sourceRef.current.parsed.offPlate.traits,
395	      }
396	      : null,
397	    setOffPlateHighlight,
398	    convert,
399	    /** Seul un G-code polaire (natif Apex ou converti) s'exporte pour l'Apex. */
400	    canExport: fileInfo?.kind === 'polar' && conversion.status !== 'running',
401	    exportGCode,
402	    /** Conversion possible ici : application de bureau, ou serveur de développement Vite. */
403	    conversionAvailable: isConversionAvailable(),
404	  };
405	}
