/** Diamètre de filament par défaut (PLA 1,75 mm) — repli si l'en-tête ne le précise pas, comme dans
 * `parseGCode` ; le débit volumétrique n'a besoin ici que d'un ordre de grandeur cohérent avec
 * `deposits[]`, jamais stocké séparément (cf. plan §1.4). */
const FALLBACK_FILAMENT_DIAMETER_MM = 1.75;

/** Valeur brute d'un mode continu au mouvement `k` — mêmes ratios dérivés qu'à l'agrégation des
 * `ranges` dans `parseGCode` (débit volumétrique, pression d'extrusion, vitesse relative de
 * couche) : recalculés à la volée plutôt que stockés, purs ratios sans mémoire propre. */
export function valueForMode(mode: ContinuousColorByMode, k: number, parsed: ParsedGCode): number {
  const mv: GCodeMove = parsed.moves[k];
  switch (mode) {
    case 'speed': return parsed.speedMmS[k];
    case 'accel': return parsed.accelMmS2[k];
    case 'headAngle': return Math.abs(mv.b);
    case 'segmentLength': return parsed.segLengthMm[k];
    case 'elapsedTime': return parsed.times[k];
    case 'lineWidth': return parsed.widthMm[k];
    case 'layerHeight': return parsed.layerHeightMm[k];
    case 'temperature': return parsed.nozzleTempC[k];
    case 'fanSpeed': return parsed.fanPct[k];
    case 'extrusionRatio': {
      const len = parsed.segLengthMm[k];
      if (!mv.extruding || len <= 1e-6) return NaN;
      // Filament déposé (mm) au mouvement k = fraction de la déformation E qui n'est pas la
      // réinjection d'une rétraction — non conservée séparément ; ré-estimée depuis speedMmS et
      // segLengthMm serait moins fidèle, donc on ne peut que reconstituer un ratio équivalent via
      // le débit volumétrique déjà cohérent (mêmes grandeurs que `parseGCode`, cf. volumetricFlow).
      const dt = k > 0 ? Math.max(1e-9, parsed.times[k] - parsed.times[k - 1]) : 1e-9;
      const flow = volumetricFlow(mode, k, parsed, dt);
      if (Number.isNaN(flow)) return NaN;
      const areaMm2 = Math.PI * (FALLBACK_FILAMENT_DIAMETER_MM / 2) ** 2;
      return (flow * dt) / areaMm2 / len;
    }
    case 'volumetricFlow': {
      if (!mv.extruding) return NaN;
      const dt = k > 0 ? parsed.times[k] - parsed.times[k - 1] : 0;
      return volumetricFlow(mode, k, parsed, dt);
    }
    case 'layerSpeedRatio': {
      const maxSpeed = parsed.layerMaxSpeedMmS[k];
      if (!mv.extruding || maxSpeed <= 1e-6) return NaN;
      return (parsed.speedMmS[k] / maxSpeed) * 100;
    }
  }
}

/** Débit volumétrique (mm³/s) au mouvement `k`, à partir de la vitesse et de la section nominale du
 * cordon (largeur × hauteur de couche si connues, sinon une section de filament de repli) — une
 * estimation cohérente avec `extrusionRatio` ci-dessus sans dupliquer `deposits[]`, non retourné
 * par `parseGCode`. */
function volumetricFlow(_mode: 'volumetricFlow' | 'extrusionRatio', k: number, parsed: ParsedGCode, dt: number): number {
  if (dt <= 1e-9) return NaN;
  const width = parsed.widthMm[k];
  const height = parsed.layerHeightMm[k];
  const areaMm2 = !Number.isNaN(width) && !Number.isNaN(height) && width > 0 && height > 0
    ? width * height
    : Math.PI * (FALLBACK_FILAMENT_DIAMETER_MM / 2) ** 2 * 0.25; // section de cordon nominale de repli
  return areaMm2 * parsed.speedMmS[k];
}

