    : Math.PI * (FALLBACK_FILAMENT_DIAMETER_MM / 2) ** 2 * 0.25; // section de cordon nominale de repli
  return areaMm2 * parsed.speedMmS[k];
}

/** Couleur pour le mode `mode` au mouvement `k`, écrite dans `out`. Le mode catégoriel
 * (« lineType ») n'est jamais routé ici — ses couleurs viennent directement de LINE_TYPES. */
export function colorForMode(
  mode: ContinuousColorByMode,
  k: number,
  parsed: ParsedGCode,
  ranges: ColorByRanges,
  out: BABYLON.Color3,
): BABYLON.Color3 {
  const value = valueForMode(mode, k, parsed);
  const t = Number.isNaN(value) ? 0.5 : normalize(value, ranges[mode]);
