toolUseResult.originalFile:
// Légende « Type de ligne » : même vocabulaire visuel que GCodeSpeedSelector (libellés 11px/600
// blancs translucides, cyan pour l'état actif) dans le verre du panneau du haut de Prévisualisation.
.root {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 12px 8px 10px 12px;
}

// En-tête et lignes partagent la même grille ; `scrollbar-gutter` réserve la même largeur de barre
// de défilement des deux côtés pour garder les colonnes alignées.
.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 62px 48px 46px 16px;
  column-gap: 5px;
  align-items: center;
  padding: 0 6px;
}

.header {
  flex: 0 0 auto;
  height: 26px;
  overflow-y: hidden;
  scrollbar-gutter: stable;
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.rows {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.row {
  height: 22px;
  border-radius: 6px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.06);
  }
}

.name {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.swatch {
  flex: 0 0 10px;
  height: 10px;
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.numeric {
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.row .numeric {
  font-size: 10.5px;
  color: rgba(255, 255, 255, 0.7);
}

.row .dash {
  color: rgba(255, 255, 255, 0.25);
}

// Type masqué dans le viewport : ligne atténuée, case restant pleinement lisible.
.off {
  .name,
  .numeric {
    opacity: 0.4;
  }
}

.checkbox {
  appearance: none;
  justify-self: end;
  width: 16px;
  height: 16px;
  margin: 0;
  border-radius: 5px;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  cursor: pointer;
  position: relative;
  transition: all 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.14);
  }

  &:checked {
    background: rgba(0, 240, 255, 0.18);
    box-shadow: 0 0 8px rgba(0, 240, 255, 0.25);

    &::after {
      content: '';
      position: absolute;
      left: 5px;
      top: 2px;
      width: 4px;
      height: 9px;
      border: solid #00f0ff;
      border-width: 0 1px 1px 0;
      transform: rotate(45deg);
    }
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

// --- Sélecteur « Colorer par » (GCodeColorBySelector) ------------------------------------------

.colorByTrigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 26px;
  margin-bottom: 6px;
  padding: 0 8px 0 6px;
  border: none;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.colorByTriggerLabel {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
}

.colorByTriggerValue {
  font-size: 11px;
  font-weight: 600;
  color: #00f0ff;
}

