1	import React from 'react';
2	import { motion } from 'framer-motion';
3	import clsx from 'clsx';
4	import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
5	import { LINE_TYPES, type LineTypeId, type LineTypeVisibility } from './gcodeLineTypes';
6	import type { ColorByMode, ContinuousColorByMode } from './gcodeLayer';
7	import { COLOR_BY_LABELS, COLOR_BY_UNITS, COLORMAP_STOPS_HEX } from './gcodeColormap';
8	import type { GCodeFileInfo } from '@/hooks/use-gcode-preview';
9	import styles from './GCodeLineTypeLegend.module.scss';
10	
11	interface GCodeLineTypeLegendProps {
12	  /** G-code chargé (statistiques par type de ligne), ou null : toutes les valeurs en « — ». */
13	  fileInfo: GCodeFileInfo | null;
14	  visibility: LineTypeVisibility;
15	  onToggle: (id: LineTypeId, visible: boolean) => void;
16	  /** Critère de coloration actif du tracé (cf. gcodeColormap.ts). */
17	  colorBy: ColorByMode;
18	  setColorBy: (mode: ColorByMode) => void;
19	}
20	
21	const DASH = '—';
22	
23	const formatNumber = (value: number, digits: number) => value.toFixed(digits).replace('.', ',');
24	
25	/** « 8 m 45 s », « 12 s » ; heures sans secondes (« 1 h 12 m ») pour tenir dans la colonne. */
26	const formatDuration = (seconds: number) => {
27	  const total = Math.round(seconds);
28	  if (total === 0) return '< 1 s';
29	  const h = Math.floor(total / 3600);
30	  const m = Math.floor((total % 3600) / 60);
31	  const s = total % 60;
32	  if (h > 0) return `${h} h ${m} m`;
33	  return m > 0 ? `${m} m ${s} s` : `${s} s`;
34	};
35	
36	/** Valeur d'un mode continu, avec l'unité du mode — 2 décimales pour les grandeurs sous 10 (mm,
37	 * mm/mm...), sans décimale au-delà (mm/s, °C, %...) pour rester lisible. */
38	const formatColorByValue = (mode: ContinuousColorByMode, value: number) => {
39	  const digits = Math.abs(value) < 10 ? 2 : 0;
40	  return `${formatNumber(value, digits)} ${COLOR_BY_UNITS[mode]}`;
41	};
42	
43	// Même cascade d'apparition que GCodeSpeedSelector (fondu-montée, easing « standard » Material).
44	const containerVariants = {
45	  hidden: {},
46	  visible: { transition: { staggerChildren: 0.02 } },
47	};
48	const itemVariants = {
49	  hidden: { opacity: 0, y: 6 },
50	  visible: { opacity: 1, y: 0, transition: { duration: 0.22, ease: [0.4, 0, 0.2, 1] as const } },
