// Légende « Type de ligne » : même vocabulaire visuel que GCodeSpeedSelector (libellés 11px/600
// blancs translucides, cyan pour l'état actif) dans le verre du panneau du haut de Prévisualisation.
.root {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 12px 8px 10px 12px;
}

// En-tête et lignes partagent la même grille ; `scrollbar-gutter` réserve la même largeur de barre
// de défilement des deux côtés pour garder les colonnes alignées.
.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 62px 48px 46px 16px;
  column-gap: 5px;
  align-items: center;
  padding: 0 6px;
}

.header {
  flex: 0 0 auto;
  height: 26px;
  overflow-y: hidden;
  scrollbar-gutter: stable;
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.rows {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.row {
  height: 22px;
  border-radius: 6px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.06);
  }
}

.name {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.swatch {
  flex: 0 0 10px;
  height: 10px;
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.numeric {
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.row .numeric {
  font-size: 10.5px;
  color: rgba(255, 255, 255, 0.7);
}

.row .dash {
  color: rgba(255, 255, 255, 0.25);
}

// Type masqué dans le viewport : ligne atténuée, case restant pleinement lisible.
.off {
  .name,
  .numeric {
    opacity: 0.4;
  }
}

.checkbox {
  appearance: none;
  justify-self: end;
  width: 16px;
  height: 16px;
  margin: 0;
  border-radius: 5px;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  cursor: pointer;
  position: relative;
  transition: all 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.14);
  }

  &:checked {
    background: rgba(0, 240, 255, 0.18);
    box-shadow: 0 0 8px rgba(0, 240, 255, 0.25);

    &::after {
      content: '';
      position: absolute;
      left: 5px;
      top: 2px;
      width: 4px;
      height: 9px;
      border: solid #00f0ff;
      border-width: 0 1px 1px 0;
      transform: rotate(45deg);
    }
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

// --- Sélecteur « Colorer par » (GCodeColorBySelector) ------------------------------------------

.colorByTrigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 26px;
  margin-bottom: 6px;
  padding: 0 8px 0 6px;
  border: none;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.colorByTriggerLabel {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
}

.colorByTriggerValue {
  font-size: 11px;
  font-weight: 600;
  color: #00f0ff;
}

// Contenu du popover : fond clair (demandé pour lire le texte en noir), au lieu du verre sombre du
// reste du panneau. Rendu dans un Portal (document.body, hors du panneau et de son
// `isolation: isolate`) : son z-index doit donc dépasser celui du panneau le plus élevé de
// CategoriesSidebar (1003), sans quoi il s'affiche derrière lui.
.colorByMenu {
  // !important : neutralise la classe Tailwind `z-50` du composant shadcn par défaut (même
  // spécificité, ordre d'injection CSS non garanti entre Tailwind et les modules SCSS).
  z-index: 1100 !important;
  color: #1a1a1a !important;
  width: 236px;
  max-height: 320px;
  overflow-y: auto;
  padding: 6px;
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 10px;
  background: #f5f5f7;
  box-shadow: 0 8px 24px 0 rgba(0, 0, 0, 0.35);
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 0, 0, 0.18) transparent;
}

.colorByGroup {
  margin-top: 8px;

  &:first-child {
    margin-top: 4px;
  }
}

.colorByGroupLabel {
  padding: 4px 8px 2px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: rgba(0, 0, 0, 0.45);
}

.colorByItem {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 28px;
  padding: 0 8px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: #1a1a1a;
  font-size: 12px;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(0, 0, 0, 0.06);
  }
}

.colorByItemActive {
  background: rgba(0, 150, 170, 0.14);
  color: #007a8a;
}

.colorByItemSwatch {
  flex: 0 0 20px;
  height: 6px;
  border-radius: 3px;
}

// --- Corps de la légende en mode continu (dégradé + min/moy/max) -------------------------------

.gradientPanel {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 14px;
  padding: 8px 6px;
}

.gradientBar {
  height: 10px;
  border-radius: 5px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.gradientStats {
  display: flex;
  justify-content: space-between;
}

.gradientStat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.gradientStatLabel {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.gradientStatValue {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
  font-variant-numeric: tabular-nums;
}

.gradientEmpty {
  margin: 0;
  text-align: center;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.4);
}

