.fusionMenuContainer {
  position: fixed;
  left: 24px;
  top: 280px;
  width: 320px;
  max-height: 400px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 16px;
  z-index: 1001;
  display: flex;
  flex-direction: column;
  overflow: visible;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }

  > * {
    transition: opacity 0.2s ease;
  }

  // Pendant le morphing d'ouverture/fermeture, le verre animé (LiquidGlassMorph) tient lieu de
  // fond : celui du panneau disparaît instantanément et le contenu s'estompe par-dessus.
  &.morphing {
    box-shadow: none;

    &::before {
      opacity: 0;
    }

    > * {
      opacity: 0;
    }
  }
}

// Le mécanisme d'ouverture/fermeture du panneau est fonctionnel, mais son contenu (réglages
// qualité/solidité/vitesse) n'est pas encore branché : grisé et non interactif, tooltip "Arrive
// bientôt" sur chaque ligne (cf. CategoriesSidebar.tsx).
.contentInert {
  opacity: 0.45;
  filter: grayscale(1);

  .itemRow {
    cursor: default;
    pointer-events: none;
  }

  // grayscale() désature mais ne neutralise pas la luminosité : le cyan très saturé de
  // .itemInput (#00f0ff, cf. plus bas) restait visuellement "vif" une fois désaturé en gris
  // clair. On écrase sa couleur ici pour un gris terne sans ambiguïté.
  .itemInput {
    color: rgba(255, 255, 255, 0.5);
  }
}

.fusionMenuContent {
  padding: 16px;
  overflow-y: scroll;
  max-height: 400px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-radius: 16px;

  &::-webkit-scrollbar {
    width: 0px;
    background: transparent;
  }
}

.externalScrollThumb {
  position: absolute;
  left: calc(100% + 4px);
  width: 6px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-radius: 999px;
  pointer-events: auto;
  cursor: default;
  z-index: 1002;
  transition: width 0.25s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease;

  &:hover, &.dragging {
    width: 12px;
    background: rgba(255, 255, 255, 0.35);
  }
}

.sectionGroup {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sectionTitle {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.5px;
}

.itemsList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.itemRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.9);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  transform: perspective(400px) translateZ(0px);

  &.clickableRow {
    cursor: pointer;

    &:hover {
      background: rgba(255, 255, 255, 0.12);
      border-color: rgba(255, 255, 255, 0.2);
      transform: perspective(400px) translateZ(6px);
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
    }
  }

  &:not(.clickableRow):hover {
    background: rgba(255, 255, 255, 0.08);
    transform: perspective(400px) translateZ(4px);
  }
}

.itemName {
  flex: 1;
  padding-right: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.itemInput {
  width: 55px;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 4px;
  color: #00f0ff;
  text-align: center;
  font-size: 11px;
  padding: 2px 4px;
  outline: none;

  &:focus {
    border-color: #00f0ff;
    box-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
  }
}

.dropdownTrigger {
  display: flex;
