305	}) => {
306	  const iconRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});
307	  const categoriesToolbarRef = useRef<HTMLDivElement>(null);
308	  const contentRef = useRef<HTMLDivElement>(null);
309	  const patternContentRef = useRef<HTMLDivElement>(null);
310	
311	  const [thumbHeight, setThumbHeight] = useState(40);
312	  const [thumbTop, setThumbTop] = useState(8);
313	  const [hasScroll, setHasScroll] = useState(false);
314	  const [isDragging, setIsDragging] = useState(false);
315	
316	  const [patternThumbHeight, setPatternThumbHeight] = useState(40);
317	  const [patternThumbTop, setPatternThumbTop] = useState(8);
318	  const [hasPatternScroll, setHasPatternScroll] = useState(false);
319	  const [isPatternDragging, setIsPatternDragging] = useState(false);
320	
321	  const [selectedPattern, setSelectedPattern] = useState<string>('Gyroïde');
322	  const [isPatternPopupOpen, setIsPatternPopupOpen] = useState(false);
323	  const [previewActive, setPreviewActive] = useState(initialPreviewActive);
324	  // Figé au montage, jamais réévalué : `initialPreviewActive` (la PROP) suit isPreviewActive en
325	  // direct côté Index.tsx, qui devient vrai dès le tout début de la mitose normale (avant même
326	  // qu'elle soit terminée) — si le JSX plus bas réagissait à la prop plutôt qu'à cette valeur
327	  // figée, le panneau du bas basculerait du <div> normal vers le motion.div spécial EN PLEINE
328	  // mitose (un changement de `key`, donc démontage/remontage avec `initial={{opacity:0,x:-20}}`) :
329	  // exactement le clignotement observé, à la toute fin du dévoilement du rideau.
330	  const [wasInitialPreviewActive] = useState(initialPreviewActive);
331	  // Même principe : figé au montage (Index.tsx remet la prop à `false` juste après).
332	  const [wasArrivingFromModeling] = useState(arrivingFromModeling);
333	
334	  // Morphings "verre liquide" (cf. LiquidGlassMorph). Pendant qu'une forme animée est à l'écran,
335	  // les vrais éléments restent montés mais sans fond (classe .morphing) : seul leur contenu
336	  // s'estompe, par-dessus le verre animé qui en tient lieu.
337	  //
338	  // Menu de catégorie :
339	  //  - 'dividing' : la pilule enfante le panneau détaillé (ouverture)
340	  //  - 'merging'  : le panneau remonte se refondre dans la pilule (fermeture)
341	  const [morphPhase, setMorphPhase] = useState<'dividing' | 'merging' | null>(null);
342	  const menuContainerRef = useRef<HTMLDivElement>(null);
343	
344	  // Espace Prévisualisation : à l'entrée, la pilule s'étire en panneau du haut, PUIS ce panneau
345	  // enfante celui du bas (deux temps successifs d'une même timeline, cf. previewPathAt) ; les deux
346	  // panneaux restent affichés tant qu'on reste dans l'espace. À la sortie, la même timeline est
347	  // rejouée à l'envers (reverse) : les deux panneaux se refondent en pilule.
348	  //  - 'forward' : pilule → panneau haut → panneau bas (ouverture)
349	  //  - 'reverse' : panneau bas → panneau haut → pilule (fermeture)
350	  const [previewMorphPhase, setPreviewMorphPhase] = useState<'forward' | 'reverse' | null>(null);
351	  const [previewPanelsBorn, setPreviewPanelsBorn] = useState(initialPreviewActive);
352	  const previewActiveRef = useRef(initialPreviewActive);
353	  // Repousse la pilule quand l'arborescence des modèles (ModelStatusBox, juste au-dessus) déborde
354	  // de sa hauteur de base, plutôt que de la laisser recouverte (cf. apex-model-tree-resized).
355	  const [modelTreeOverflow, setModelTreeOverflow] = useState(0);
356	  const onSelectCategoryRef = useRef(onSelectCategory);
357	  onSelectCategoryRef.current = onSelectCategory;
358	
359	  const startYRef = useRef(0);
360	  const startScrollTopRef = useRef(0);
361	
362	  useEffect(() => {
363	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
364	      const active = !!e.detail?.active;
365	      if (active && !previewActiveRef.current) {
366	        // La pilule devient le panneau du haut : un menu de catégorie encore ouvert se ferme
367	        // sans animation plutôt que de se superposer à la mitose.
368	        setMorphPhase(null);
369	        onSelectCategoryRef.current(null);
370	        setPreviewPanelsBorn(false);
371	        setPreviewMorphPhase('forward');
372	      } else if (!active && previewActiveRef.current) {
373	        // Sortie de l'espace : les deux panneaux se refondent en pilule (même timeline, à
374	        // l'envers) avant de démonter — jamais de disparition instantanée. `previewActive` lui-
375	        // même ne repasse à false qu'à la fin de cette animation (cf. onDone du morph), pour que
376	        // les panneaux réels restent montés (silencieux, cf. .morphing) tout du long.
377	        setPreviewMorphPhase('reverse');
378	        return;
379	      }
380	      previewActiveRef.current = active;
381	      setPreviewActive(active);
382	    };
383	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
384	    return () => {
385	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
386	    };
387	  }, []);
388	
389	  useEffect(() => {
390	    const handleModelTreeResized = (e: CustomEvent<{ overflow: number }>) => {
391	      setModelTreeOverflow(e.detail?.overflow ?? 0);
392	    };
393	    window.addEventListener('apex-model-tree-resized', handleModelTreeResized as EventListener);
394	    return () => {
395	      window.removeEventListener('apex-model-tree-resized', handleModelTreeResized as EventListener);
396	    };
