// Déclencheur du sélecteur « colorer par » : le libellé de l'en-tête de colonne LUI-MÊME (« Type de
// ligne », ou le nom du mode actif), pas un bandeau séparé — cadre visible seulement au survol,
// chevron toujours accolé pour signaler qu'il ouvre un menu.
.colorByTrigger {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  margin: 0 -6px 0 -2px;
  padding: 0 6px 0 2px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.18);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.colorByChevron {
  flex: 0 0 auto;
  opacity: 0.7;
}

// Contenu du popover : fond clair (demandé pour lire le texte en noir), au lieu du verre sombre du
// reste du panneau. Rendu dans un Portal (document.body, hors du panneau et de son
// `isolation: isolate`) : son z-index doit donc dépasser celui du panneau le plus élevé de
// CategoriesSidebar (1003), sans quoi il s'affiche derrière lui.
// Même verre que Sidebar.module.scss (.toolbar) : fond sombre translucide + flou d'arrière-plan,
// au lieu du popover shadcn par défaut (clair, non assorti au reste de l'app).
.colorByMenu {
  // !important : neutralise la classe Tailwind `z-50` du composant shadcn par défaut (même
  // spécificité, ordre d'injection CSS non garanti entre Tailwind et les modules SCSS).
  z-index: 1100 !important;
  color: rgba(255, 255, 255, 0.85) !important;
  width: 236px;
  max-height: 320px;
  overflow-y: auto;
  padding: 6px;
  border: none;
  border-radius: 10px;
  background: rgba(10, 15, 26, 0.65);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 12px 40px 0 rgba(0, 0, 0, 0.45), 0 4px 16px 0 rgba(0, 0, 0, 0.3);
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.colorByGroup {
  margin-top: 8px;

  &:first-child {
    margin-top: 4px;
  }
}

.colorByGroupLabel {
  padding: 4px 8px 2px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.4);
}

.colorByItem {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 28px;
  padding: 0 8px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: rgba(255, 255, 255, 0.85);
  font-size: 12px;
  text-align: left;
  cursor: pointer;
  outline: none;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
  }

  &:focus-visible {
    box-shadow: inset 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.colorByItemActive {
  background: rgba(0, 240, 255, 0.16);
  color: #00f0ff;
}

.colorByItemSwatch {
  flex: 0 0 20px;
  height: 6px;
  border-radius: 3px;
}

// --- Corps de la légende en mode continu (dégradé + min/moy/max) -------------------------------

