// Popover : même design que les menus de catégorie de CategoriesSidebar.module.scss
// (.fusionMenuContainer/.itemRow/.sectionTitle/.externalScrollThumb), recopié fidèlement ici plutôt
// que partagé entre modules CSS (couplage fragile) — verre sombre + flou, cartes de ligne, curseur
// de défilement externe glissable. Rendu dans un Portal (document.body, hors du panneau et de son
// `isolation: isolate`) : son z-index doit donc dépasser celui du panneau le plus élevé de
// CategoriesSidebar (1003), sans quoi il s'affiche derrière lui.
.colorByMenu {
  // !important : neutralise la classe Tailwind `z-50` du composant shadcn par défaut (même
  // spécificité, ordre d'injection CSS non garanti entre Tailwind et les modules SCSS).
  z-index: 1100 !important;
  position: relative;
  width: 260px;
  padding: 0;
  border: none;
  border-radius: 16px;
  overflow: visible;
  isolation: isolate;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.65);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.colorByMenuContent {
  max-height: 320px;
  overflow-y: scroll;
  padding: 16px;
  display: flex;
  flex-direction: column;
