}

.gradientStats {
  display: flex;
  justify-content: space-between;
}

.gradientStat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.gradientStatLabel {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.gradientStatValue {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
