// Échelle verticale : la barre (Max en haut, Min en bas — sens habituel d'une légende thermique)
// et la colonne Min/Moy./Max côte à côte, chacune alignée sur son repère le long de la barre.
.gradientScale {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  gap: 14px;
  padding: 4px 8px 4px 0;
}

.gradientBar {
  flex: 0 0 10px;
  width: 10px;
  // Rouge (max) en haut, bleu (min) en bas : sens inverse de la rampe horizontale d'origine
  // (gcodeColormap.ts va du bleu au rouge de gauche à droite), donc le dégradé est retourné ici.
  background: linear-gradient(0deg, var(--gcode-gradient-stops));
  border-radius: 5px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

