  // garanti, donc SANS !important certaines de ces propriétés s'affichaient (z-index, fond, ombre
  // déjà rencontrés un par un) et d'autres non selon l'ordre du jour, silencieusement. Plus fiable
  // de neutraliser tout le lot d'un coup que de découvrir chaque propriété écrasée au cas par cas.
  z-index: 1100 !important;
  position: relative !important;
  background: rgba(10, 15, 26, 0.65) !important;
  // Même intensité que Sidebar.module.scss (.toolbar) — 16px était trop prononcé pour ce menu.
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  width: 260px !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 16px !important;
  overflow: visible !important;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3) !important;
}

.colorByMenuContent {
  max-height: 320px;
  overflow-y: scroll;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-radius: inherit;
  color: rgba(255, 255, 255, 0.85);

  &::-webkit-scrollbar {
    width: 0;
    background: transparent;
  }
}

// Même piste que .externalScrollThumb (CategoriesSidebar.module.scss) : hors du conteneur
// scrollable, posée à droite du menu, glissable (cf. useExternalScrollThumb).
.externalScrollThumb {
  position: absolute;
  left: calc(100% + 4px);
  width: 6px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-radius: 999px;
  pointer-events: auto;
  cursor: default;
  z-index: 1;
  transition: width 0.25s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease;

  &:hover,
  &.dragging {
    width: 12px;
    background: rgba(255, 255, 255, 0.35);
  }
}

.sectionGroup {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sectionTitle {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.5px;
}

.itemsList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.itemRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.9);
  cursor: pointer;
  outline: none;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  transform: perspective(400px) translateZ(0px);

  &:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 255, 255, 0.2);
    transform: perspective(400px) translateZ(6px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.activeItemRow {
  background: rgba(0, 240, 255, 0.14);
  border-color: rgba(0, 240, 255, 0.3);
  color: #00f0ff;
}

.itemName {
  flex: 1;
  padding-right: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}

.colorByItemSwatch {
  flex: 0 0 20px;
  height: 6px;
  border-radius: 3px;
}

// --- Corps de la légende en mode continu (dégradé + min/moy/max) -------------------------------

.gradientPanel {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 8px 6px;
}

// Échelle verticale : la barre (Max en haut, Min en bas — sens habituel d'une légende thermique)
// et la colonne Min/Moy./Max côte à côte, chacune alignée sur son repère le long de la barre.
.gradientScale {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  gap: 14px;
  padding: 4px 8px 4px 0;
}

.gradientBar {
  flex: 0 0 10px;
  width: 10px;
  border-radius: 5px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.gradientStats {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.gradientStat {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

// Le repère « Moy. » (au milieu de la barre) reste centré verticalement même si Min/Max, eux,
// s'alignent sur le haut/bas de la colonne (justify-content: space-between du parent).
.gradientStatAvg {
  align-self: center;
  text-align: center;
}

.gradientStatMax {
  text-align: right;
}

.gradientStatLabel {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.gradientStatValue {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
  font-variant-numeric: tabular-nums;
}

.gradientEmpty {
  margin: 0;
  text-align: center;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.4);
}

