1	import { useCallback, useEffect, useRef, useState } from 'react';
2	import { showError, showSuccess, showWarning } from '@/utils/toast';
3	import {
4	  parseGCode,
5	  stateAt,
6	  timeAtIndex,
7	  indexAtTime,
8	  SUSPICIOUS_C_RANGE_DEG,
9	  PLATE_RADIUS_MM,
10	  type ParsedGCode,
11	  type GCodeKind,
12	  type LineTypeStat,
13	  type ConversionMode,
14	  type ColorByMode,
15	  type ColorByRanges,
16	} from '@/components/gcodeLayer';
17	import { DEFAULT_LINE_VISIBILITY, type LineTypeId, type LineTypeVisibility } from '@/components/gcodeLineTypes';
18	import type { GCodeGenerator } from '@/components/gcodeGenerator';
19	import { isConversionAvailable, runConversion } from '@/utils/gcodeConversion';
20	
21	/**
22	 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
23	 * la fenêtre ou sélecteur), horloge de lecture et affichage des trajets à vide. Le rendu 3D est
24	 * fait par Viewport3D, piloté par les événements :
25	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
26	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
27	 *  - `apex-gcode-line-visibility` { visibility } : types de ligne affichés (cf. gcodeLineTypes.ts) ;
28	 *  - `apex-gcode-color-by` { mode } : critère de coloration du tracé (cf. gcodeColormap.ts).
29	 */
30	
31	// Multiplicateurs du temps machine réel (1 = vitesse d'impression réelle, avances F du fichier).
32	export const GCODE_SPEED_OPTIONS = [0.01, 1, 4, 16, 64, 256];
33	export const GCODE_ACCEPT = '.gcode,.gco,.g,.ngc';
34	/** Reconnaît un nom de fichier G-code par son extension — exporté pour Sidebar.tsx (bascule
35	 * automatique vers l'espace Prévisualisation au dépôt d'un tel fichier en Préparation). */
36	export const GCODE_FILE_EXT = /\.(gcode|gco|g|ngc)$/i;
37	
38	export interface GCodeFileInfo {
39	  name: string;
40	  kind: GCodeKind;
41	  lineStats: Record<LineTypeId, LineTypeStat>;
42	  /** Temps machine total (s). */
43	  totalTime: number;
44	  generator: GCodeGenerator | null;
45	  printer: string | null;
46	  /** 3 axes à Z variable dans les couches : l'angle dynamique est recommandé pour la conversion. */
47	  nonPlanar: boolean;
48	  /** Fichier issu de la conversion polaire d'Apex (mode), sinon null. */
49	  conversion: ConversionMode | null;
50	  moves: number;
51	  extruding: number;
52	  minZ: number;
53	  maxZ: number;
54	  minC: number;
55	  maxC: number;
56	  /** Min/max/moyenne de chaque critère de coloration continu, pour le dégradé de la légende
57	   * (cf. GCodeLineTypeLegend.tsx et gcodeColormap.ts). */
58	  colorByRanges: ColorByRanges;
59	}
60	
61	export interface ConversionState {
62	  status: 'idle' | 'running' | 'done' | 'error';
63	  /** Avancement 0–100 pendant la conversion. */
64	  progress: number;
65	  /** Mode demandé (en cours) ou obtenu (terminé). */
66	  mode: ConversionMode | null;
67	  error: string | null;
68	}
69	
70	const IDLE_CONVERSION: ConversionState = { status: 'idle', progress: 0, mode: null, error: null };
71	
72	/** Surlignage rouge, dans le viewport, des traits hors plateau de la source 3 axes affichée. */
73	const setOffPlateHighlight = (show: boolean) =>
74	  window.dispatchEvent(new CustomEvent('apex-gcode-highlight-offplate', { detail: { show } }));
75	
76	const dispatchTime = (t: number) =>
77	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
78	
79	/** @param active Espace Prévisualisation affiché (active le dépôt de fichier, coupe la lecture sinon). */
80	export function useGCodePreview(active: boolean) {
81	  const parsedRef = useRef<ParsedGCode | null>(null);
82	  const tRef = useRef(0);
83	  const dragDepthRef = useRef(0);
84	
85	  const [fileInfo, setFileInfo] = useState<GCodeFileInfo | null>(null);
86	  const [t, setT] = useState(0);
87	  const [isPlaying, setIsPlaying] = useState(false);
88	  const [speed, setSpeed] = useState(GCODE_SPEED_OPTIONS[1]);
89	  const [lineVisibility, setLineVisibility] = useState<LineTypeVisibility>(DEFAULT_LINE_VISIBILITY);
90	  const [showFullHead, setShowFullHead] = useState(true);
91	  /** Critère de coloration du tracé (cf. gcodeColormap.ts) ; remis à `lineType` à chaque nouveau
92	   * fichier chargé (cf. `loadText`), comme les autres réglages qui n'ont plus de sens d'un fichier
93	   * à l'autre. */
94	  const [colorBy, setColorByState] = useState<ColorByMode>('lineType');
95	  const [isDragging, setIsDragging] = useState(false);
96	  // Le temps de lire le fichier et de parser son texte (`loadFile`, ci-dessous) : permet à
97	  // GCodePreviewBar de s'afficher dès le début du chargement plutôt que d'attendre `fileInfo`.
98	  const [isLoading, setIsLoading] = useState(false);
99	  // Fichier 3 axes chargé par l'utilisateur (source de la conversion polaire, gardée après
100	  // conversion pour reconvertir dans l'autre mode) et G-code actuellement affiché (celui exporté).
101	  const sourceRef = useRef<{ text: string; name: string; parsed: ParsedGCode } | null>(null);
102	  const currentRef = useRef<{ text: string; name: string } | null>(null);
103	  const [conversion, setConversion] = useState<ConversionState>(IDLE_CONVERSION);
104	
105	  useEffect(() => {
106	    if (!active) setIsPlaying(false);
107	  }, [active]);
108	
109	  useEffect(() => {
110	    window.dispatchEvent(new CustomEvent('apex-gcode-line-visibility', { detail: { visibility: lineVisibility } }));
111	  }, [lineVisibility]);
112	
113	  // Stable : la légende (mémoïsée) ne doit pas se redessiner à chaque rafraîchissement de lecture.
114	  const setLineVisible = useCallback((id: LineTypeId, visible: boolean) =>
115	    setLineVisibility((prev) => ({ ...prev, [id]: visible })), []);
116	
117	  useEffect(() => {
118	    window.dispatchEvent(new CustomEvent('apex-gcode-color-by', { detail: { mode: colorBy } }));
119	  }, [colorBy]);
120	
121	  const setColorBy = useCallback((mode: ColorByMode) => setColorByState(mode), []);
122	
123	  useEffect(() => {
124	    window.dispatchEvent(new CustomEvent('apex-gcode-show-full-head', { detail: { show: showFullHead } }));
125	  }, [showFullHead]);
126	
127	  // Horloge de lecture : avance le temps machine (durées réelles des mouvements, cf.
128	  // `ParsedGCode.times`) à `speed` × le temps réel, le reconvertit en index de mouvement `t`,
129	  // pousse chaque image au viewport et rafraîchit l'état React à ~20 Hz seulement.
130	  useEffect(() => {
131	    if (!isPlaying) return;
132	    const parsed = parsedRef.current;
133	    if (!parsed) return;
134	    const last = parsed.moves.length - 1;
135	    let raf = 0;
136	    let prev = performance.now();
137	    let sinceUiSync = 0;
138	    const step = (now: number) => {
139	      const dt = (now - prev) / 1000;
140	      prev = now;
141	      const s = timeAtIndex(parsed.times, tRef.current) + speed * dt;
142	      tRef.current = Math.min(last, indexAtTime(parsed.times, s));
143	      dispatchTime(tRef.current);
144	      sinceUiSync += dt;
145	      if (tRef.current >= last) {
146	        setT(last);
147	        setIsPlaying(false);
148	        return;
149	      }
150	      if (sinceUiSync > 1 / 20) {
151	        sinceUiSync = 0;
152	        setT(tRef.current);
153	      }
154	      raf = requestAnimationFrame(step);
155	    };
156	    raf = requestAnimationFrame(step);
157	    return () => cancelAnimationFrame(raf);
158	  }, [isPlaying, speed]);
159	
160	  /** Parse et affiche un G-code ; renvoie le résultat, ou null (erreur déjà signalée). */
161	  const loadText = (text: string, name: string): ParsedGCode | null => {
162	    let parsed: ParsedGCode;
163	    try {
164	      parsed = parseGCode(text);
165	    } catch {
166	      showError('Impossible de lire ce fichier G-code.');
167	      return null;
168	    }
169	    if (parsed.moves.length < 2) {
170	      showError('Aucune trajectoire exploitable dans ce fichier.');
171	      return null;
172	    }
173	
174	    parsedRef.current = parsed;
175	    currentRef.current = { text, name };
176	    const last = parsed.moves.length - 1;
177	    tRef.current = last;
178	    setIsPlaying(false);
179	    setT(last);
180	    setColorByState('lineType');
181	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
182	
183	    setFileInfo({
184	      name,
185	      kind: parsed.kind,
186	      lineStats: parsed.lineStats,
187	      totalTime: parsed.times[parsed.times.length - 1],
188	      generator: parsed.generator,
189	      printer: parsed.printer,
190	      nonPlanar: parsed.nonPlanar,
191	      conversion: parsed.conversion,
192	      moves: parsed.moves.length,
193	      extruding: parsed.extrudingCount,
194	      minZ: parsed.minZ,
195	      maxZ: parsed.maxZ,
196	      minC: parsed.minC,
197	      maxC: parsed.maxC,
198	      colorByRanges: parsed.ranges,
199	    });
200	    return parsed;
201	  };
202	
203	  const loadFile = async (file: File) => {
204	    if (!GCODE_FILE_EXT.test(file.name)) {
205	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
206	      return;
207	    }
208	    setIsLoading(true);
209	    const text = await file.text().catch(() => null);
210	    const parsed = text === null ? null : loadText(text, file.name);
211	    setIsLoading(false);
212	    if (!parsed) return;
213	
214	    // Nouveau fichier : il devient la source d'une éventuelle conversion polaire (s'il est 3 axes).
215	    sourceRef.current = parsed.kind === 'cartesian'
216	      ? { text: text!, name: file.name, parsed }
217	      : null;
218	    setConversion(IDLE_CONVERSION);
219	    setOffPlateHighlight(false);
220	
221	    // Un C qui accumule les tours est normal dans un fichier converti (le plateau suit la pièce).
222	    if (parsed.kind === 'polar' && !parsed.conversion && parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
223	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
224	    } else {
225	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
226	    }
227	  };
228	
229	  /** Convertit la source 3 axes en G-code polaire Apex (script Python de l'application de bureau)
230	   * et affiche le résultat ; la source est conservée pour reconvertir dans l'autre mode. */
231	  const convert = async (mode: ConversionMode, dropOffPlate: boolean) => {
232	    const source = sourceRef.current;
233	    if (!source || conversion.status === 'running') return;
234	    setOffPlateHighlight(false);
235	    setConversion({ status: 'running', progress: 0, mode, error: null });
236	    try {
237	      const { text, summary } = await runConversion(
238	        {
239	          text: source.text,
240	          mode,
241	          centerX: source.parsed.bedCenter.x,
242	          centerY: source.parsed.bedCenter.y,
243	          source: source.parsed.generator?.name ?? source.name,
244	          dropOutsideRadius: dropOffPlate ? PLATE_RADIUS_MM : 0,
245	        },
246	        (progress) => setConversion((prev) => (prev.status === 'running' ? { ...prev, progress } : prev)),
247	      );
248	      const name = `${source.name.replace(/\.[^.]+$/, '')}_apex${mode === 'dynamic' ? '_dynamique' : ''}.gcode`;
249	      if (!loadText(text, name)) throw new Error('Le G-code converti est illisible.');
250	      setConversion({ status: 'done', progress: 100, mode, error: null });
251	      const detail = summary
252	        ? ` (écart max ${summary.maxErrorMm.toFixed(3).replace('.', ',')} mm${mode === 'dynamic' ? `, B de ${summary.bMin.toFixed(0)}° à ${summary.bMax.toFixed(0)}°` : ''}${summary.droppedMoves ? `, ${summary.droppedMoves} mouvements hors plateau supprimés` : ''})`
253	        : '';
254	      showSuccess(`G-code converti en polaire${mode === 'dynamic' ? ' à angle dynamique' : ''}${detail}.`);
255	    } catch (err) {
256	      const message = err instanceof Error ? err.message.replace(/^Error invoking remote method '[^']+': (Error: )?/, '') : String(err);
257	      setConversion({ status: 'error', progress: 0, mode, error: message });
258	      showError(`Conversion impossible : ${message}`);
259	    }
260	  };
261	
262	  /** Enregistre le G-code affiché (boîte d'enregistrement native, ou téléchargement hors application). */
263	  const exportGCode = async () => {
264	    const current = currentRef.current;
265	    if (!current) return;
266	    try {
267	      if (window.apexDesktop) {
268	        const result = await window.apexDesktop.saveGCode(current);
269	        if (result.saved) showSuccess(`G-code exporté : ${result.path}`);
270	        return;
271	      }
272	      const url = URL.createObjectURL(new Blob([current.text], { type: 'text/plain' }));
273	      const link = document.createElement('a');
