278	    } catch (err) {
279	      showError(`Export impossible : ${err instanceof Error ? err.message : String(err)}`);
280	    }
281	  };
282	
283	  // Fichier reçu de Sidebar.tsx (dépôt en Préparation, cf. `enterPreview`) une fois la bascule
284	  // animée vers l'espace Prévisualisation terminée — dispatché seulement APRÈS
285	  // `apex-preview-toggled { active: true }`, donc toujours reçu ici avec `active` déjà vrai.
286	  // `loadFileRef` : la fonction est recréée à chaque rendu (elle ferme sur `file`, capturé par
287	  // paramètre, pas par un état qui changerait), mais l'effet ne doit s'abonner qu'une fois — sans
