289	  // seuls des setters stables (jamais lus depuis une valeur figée) sont appelés à l'intérieur.
290	  const loadFileRef = useRef(loadFile);
291	  loadFileRef.current = loadFile;
292	  useEffect(() => {
293	    const onEnteringPreviewWithFile = (e: Event) => {
294	      const file = (e as CustomEvent<{ file: File }>).detail?.file;
295	      if (file) loadFileRef.current(file);
296	    };
297	    window.addEventListener('apex-entering-preview-with-file', onEnteringPreviewWithFile);
298	    return () => window.removeEventListener('apex-entering-preview-with-file', onEnteringPreviewWithFile);
299	  }, []);
300	
301	  /** Ouvre le sélecteur de fichier système (sans élément `<input>` dans l'interface). */
302	  const openFilePicker = () => {
303	    const input = document.createElement('input');
304	    input.type = 'file';
305	    input.accept = GCODE_ACCEPT;
306	    input.onchange = () => {
307	      const file = input.files?.[0];
308	      if (file) loadFile(file);
309	    };
310	    input.click();
311	  };
312	
313	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
314	  // souris pour la caméra, aucun élément d'interface n'a donc besoin de capter le dépôt.
315	  useEffect(() => {
316	    if (!active) return;
317	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
318	    const onDragEnter = (e: DragEvent) => {
319	      if (!hasFiles(e)) return;
320	      e.preventDefault();
321	      dragDepthRef.current++;
322	      setIsDragging(true);
323	    };
324	    const onDragOver = (e: DragEvent) => {
325	      if (!hasFiles(e)) return;
326	      e.preventDefault();
327	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
328	    };
329	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
330	    const onDragLeave = (e: DragEvent) => {
331	      if (!hasFiles(e)) return;
332	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
333	      if (dragDepthRef.current === 0) setIsDragging(false);
334	    };
335	    const onDrop = (e: DragEvent) => {
336	      if (!hasFiles(e)) return;
337	      e.preventDefault();
338	      dragDepthRef.current = 0;
339	      setIsDragging(false);
340	      const file = e.dataTransfer?.files?.[0];
341	      if (file) loadFileRef.current(file);
342	    };
343	    window.addEventListener('dragenter', onDragEnter);
344	    window.addEventListener('dragover', onDragOver);
345	    window.addEventListener('dragleave', onDragLeave);
346	    window.addEventListener('drop', onDrop);
347	    return () => {
348	      window.removeEventListener('dragenter', onDragEnter);
349	      window.removeEventListener('dragover', onDragOver);
350	      window.removeEventListener('dragleave', onDragLeave);
351	      window.removeEventListener('drop', onDrop);
352	      dragDepthRef.current = 0;
353	      setIsDragging(false);
354	    };
355	  }, [active]);
356	
357	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
358	  // Viewport mis à jour immédiatement ; l'état React (qui redessine toute la page) au plus une fois
359	  // par image, pour qu'un glisser envoyant plusieurs événements par image reste fluide.
360	  const seekSyncRafRef = useRef(0);
361	  const seek = (value: number) => {
362	    setIsPlaying(false);
363	    tRef.current = value;
364	    dispatchTime(value);
365	    if (seekSyncRafRef.current) return;
366	    seekSyncRafRef.current = requestAnimationFrame(() => {
367	      seekSyncRafRef.current = 0;
368	      setT(tRef.current);
369	    });
370	  };
371	
372	  /** Lecture/pause ; repart du début si la lecture est au bout. */
373	  const togglePlay = () => {
374	    const parsed = parsedRef.current;
375	    if (!parsed) return;
376	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
377	    setIsPlaying(!isPlaying);
378	  };
379	
380	  const parsed = parsedRef.current;
381	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
382	  const current = parsed ? stateAt(parsed.moves, t) : null;
383	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
384	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
385	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
386	
387	  return {
388	    fileInfo,
389	    t,
390	    lastIndex,
391	    current,
392	    currentMove,
393	    isPlaying,
394	    togglePlay,
395	    seek,
396	    speed,
397	    setSpeed,
398	    lineVisibility,
399	    setLineVisible,
400	    showFullHead,
401	    setShowFullHead,
402	    colorBy,
403	    setColorBy,
404	    isDragging,
405	    isLoading,
406	    loadFile,
407	    openFilePicker,
408	    conversion,
409	    /** G-code 3 axes chargé, convertible en polaire (qu'il l'ait déjà été ou non), sinon null. */
410	    conversionSource: fileInfo && sourceRef.current
411	      ? {
412	        name: sourceRef.current.name,
413	        nonPlanar: sourceRef.current.parsed.nonPlanar,
414	        offPlateTraits: sourceRef.current.parsed.offPlate.traits,
415	      }
416	      : null,
417	    setOffPlateHighlight,
