1	import React from 'react';
2	import { motion } from 'framer-motion';
3	import clsx from 'clsx';
4	import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
5	import { useExternalScrollThumb } from '@/hooks/use-external-scroll-thumb';
6	import { LINE_TYPES, type LineTypeId, type LineTypeVisibility } from './gcodeLineTypes';
7	import type { ColorByMode, ContinuousColorByMode } from './gcodeLayer';
8	import { COLOR_BY_LABELS, COLOR_BY_UNITS, COLORMAP_STOPS_HEX } from './gcodeColormap';
9	import type { GCodeFileInfo } from '@/hooks/use-gcode-preview';
10	import styles from './GCodeLineTypeLegend.module.scss';
11	
12	interface GCodeLineTypeLegendProps {
13	  /** G-code chargé (statistiques par type de ligne), ou null : toutes les valeurs en « — ». */
14	  fileInfo: GCodeFileInfo | null;
15	  visibility: LineTypeVisibility;
16	  onToggle: (id: LineTypeId, visible: boolean) => void;
17	  /** Critère de coloration actif du tracé (cf. gcodeColormap.ts). */
18	  colorBy: ColorByMode;
19	  setColorBy: (mode: ColorByMode) => void;
20	}
21	
22	const DASH = '—';
23	
24	const formatNumber = (value: number, digits: number) => value.toFixed(digits).replace('.', ',');
25	
26	/** « 8 m 45 s », « 12 s » ; heures sans secondes (« 1 h 12 m ») pour tenir dans la colonne. */
27	const formatDuration = (seconds: number) => {
28	  const total = Math.round(seconds);
29	  if (total === 0) return '< 1 s';
30	  const h = Math.floor(total / 3600);
31	  const m = Math.floor((total % 3600) / 60);
32	  const s = total % 60;
33	  if (h > 0) return `${h} h ${m} m`;
34	  return m > 0 ? `${m} m ${s} s` : `${s} s`;
35	};
36	
37	/** Valeur d'un mode continu, avec l'unité du mode — 2 décimales pour les grandeurs sous 10 (mm,
38	 * mm/mm...), sans décimale au-delà (mm/s, °C, %...) pour rester lisible. */
39	const formatColorByValue = (mode: ContinuousColorByMode, value: number) => {
40	  const digits = Math.abs(value) < 10 ? 2 : 0;
41	  return `${formatNumber(value, digits)} ${COLOR_BY_UNITS[mode]}`;
42	};
43	
44	// Même cascade d'apparition que GCodeSpeedSelector (fondu-montée, easing « standard » Material).
45	const containerVariants = {
46	  hidden: {},
47	  visible: { transition: { staggerChildren: 0.02 } },
48	};
49	const itemVariants = {
50	  hidden: { opacity: 0, y: 6 },
51	  visible: { opacity: 1, y: 0, transition: { duration: 0.22, ease: [0.4, 0, 0.2, 1] as const } },
52	};
53	
54	/** Groupes du sélecteur « colorer par » (cf. GCodeColorBySelector) : le type de ligne reste seul et
55	 * toujours en tête, les modes continus sont classés par famille pour rester lisibles malgré leur
56	 * nombre (~13, trop pour un simple bouton segmenté). */
57	const COLOR_BY_GROUPS: { label: string; modes: ContinuousColorByMode[] }[] = [
58	  { label: 'Cinématique', modes: ['speed', 'accel', 'headAngle', 'segmentLength', 'elapsedTime'] },
59	  { label: 'Extrusion', modes: ['volumetricFlow', 'extrusionRatio', 'lineWidth', 'layerHeight'] },
60	  { label: 'Vitesse relative', modes: ['layerSpeedRatio'] },
61	  { label: 'Thermique / refroidissement', modes: ['temperature', 'fanSpeed'] },
62	];
63	
64	const GRADIENT_CSS = `linear-gradient(90deg, ${COLORMAP_STOPS_HEX.join(', ')})`;
65	// Barre de la légende en mode continu : verticale (Min en bas, Max en haut — sens habituel d'une
66	// échelle thermique), donc la rampe est retournée par rapport à GRADIENT_CSS (horizontal, gauche à
67	// droite = bleu → rouge dans gcodeColormap.ts).
68	const VERTICAL_GRADIENT_CSS = `linear-gradient(0deg, ${COLORMAP_STOPS_HEX.join(', ')})`;
69	
70	/**
71	 * Sélecteur du critère de coloration du tracé : pas de bandeau séparé — le libellé « Type de ligne »
72	 * de l'en-tête de colonne EST le déclencheur (cadre au survol + chevron), et prend le nom du mode
73	 * actif quand ce n'est plus le type de ligne. Menu construit sur le même design que les menus de
74	 * catégorie de CategoriesSidebar (sectionGroup/sectionTitle/itemsList/itemRow, curseur de défilement
75	 * externe — cf. useExternalScrollThumb) : groupé, trop d'options (type de ligne + une douzaine de
76	 * modes continus) pour un bouton segmenté à plat.
77	 */
78	const GCodeColorBySelector: React.FC<{ colorBy: ColorByMode; setColorBy: (mode: ColorByMode) => void }> = ({
79	  colorBy,
80	  setColorBy,
81	}) => {
82	  const [open, setOpen] = React.useState(false);
83	  const contentRef = React.useRef<HTMLDivElement>(null);
84	  const { thumbHeight, thumbTop, hasScroll, isDragging, handleScroll, handleMouseDown } = useExternalScrollThumb(contentRef);
85	  const activeLabel = colorBy === 'lineType' ? 'Type de ligne' : COLOR_BY_LABELS[colorBy];
86	
87	  return (
88	    <Popover open={open} onOpenChange={setOpen}>
89	      <PopoverTrigger asChild>
90	        <button type="button" className={styles.colorByTrigger}>
91	          <span>{activeLabel}</span>
92	          <svg className={styles.colorByChevron} width="8" height="5" viewBox="0 0 8 5" fill="none" aria-hidden>
93	            <path d="M1 1L4 4L7 1" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
94	          </svg>
95	        </button>
96	      </PopoverTrigger>
97	      <PopoverContent
98	        className={styles.colorByMenu}
99	        align="start"
100	        sideOffset={6}
101	        collisionPadding={12}
102	        onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
103	      >
104	        <div ref={contentRef} className={styles.colorByMenuContent} onScroll={handleScroll}>
105	          <ul className={styles.itemsList}>
106	            <li>
107	              <button
108	                type="button"
109	                className={clsx(styles.itemRow, styles.clickableRow, { [styles.activeItemRow]: colorBy === 'lineType' })}
110	                onClick={() => { setColorBy('lineType'); setOpen(false); }}
111	              >
112	                <span className={styles.itemName}>Type de ligne</span>
113	              </button>
114	            </li>
115	          </ul>
116	          {COLOR_BY_GROUPS.map((group) => (
117	            <div key={group.label} className={styles.sectionGroup}>
118	              <h4 className={styles.sectionTitle}>{group.label}</h4>
119	              <ul className={styles.itemsList}>
120	                {group.modes.map((mode) => (
121	                  <li key={mode}>
122	                    <button
123	                      type="button"
124	                      className={clsx(styles.itemRow, styles.clickableRow, { [styles.activeItemRow]: colorBy === mode })}
125	                      onClick={() => { setColorBy(mode); setOpen(false); }}
126	                    >
127	                      <span className={styles.itemName}>{COLOR_BY_LABELS[mode]}</span>
128	                      <span className={styles.colorByItemSwatch} style={{ background: GRADIENT_CSS }} aria-hidden />
129	                    </button>
130	                  </li>
131	                ))}
132	              </ul>
133	            </div>
134	          ))}
135	        </div>
