// --- Corps de la légende en mode continu (dégradé + curseurs + min/moy/max) --------------------

.gradientPanel {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 8px 6px;
}

// Enveloppe l'échelle + la case « hors-portée en gris » sous elle.
.gradientScaleWrap {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

// Échelle verticale : la piste de la barre (Max en haut, Min en bas — sens habituel d'une légende
// thermique) et la colonne Min/Moy./Max côte à côte, chacune alignée sur son repère le long de la
// barre.
.gradientScale {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  gap: 20px;
  padding: 12px 8px 12px 0;
}

// Piste : largeur élargie par rapport à la barre visuelle elle-même, pour laisser de la place aux
// poignées qui débordent de part et d'autre (cf. .gradientHandle) sans être coupées.
.gradientBarTrack {
  position: relative;
  flex: 0 0 20px;
  width: 20px;
}

.gradientBar {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
  border-radius: 5px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

// Poignée glissable (curseur min ou max) : cercle blanc bordé, centré horizontalement sur la barre,
// positionné verticalement par `bottom` (cf. GCodeGradientScale, fraction des bornes du fichier).
.gradientHandle {
  position: absolute;
  left: 50%;
  width: 16px;
  height: 16px;
  transform: translate(-50%, 50%);
  border-radius: 50%;
  background: #fff;
  border: 2px solid rgba(10, 15, 26, 0.85);
  box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.5);
  cursor: grab;
  touch-action: none;

  &:hover {
    box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.5), 0 0 0 4px rgba(255, 255, 255, 0.12);
  }
}

.gradientHandleActive {
  cursor: grabbing;
  box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.5), 0 0 0 5px rgba(0, 240, 255, 0.25);
}

.gradientStats {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.gradientStat {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

// Moyenne du fichier tombée hors de la portée resserrée (cf. GCodeGradientScale) : atténuée pour
// signaler qu'elle n'est plus représentative de ce qui est affiché sur le tracé.
.gradientStatOutOfScope {
  opacity: 0.4;
}

.gradientStatLabel {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.gradientStatValue {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
  font-variant-numeric: tabular-nums;
}

// Case « hors-portée en gris » : même vocabulaire visuel que .checkboxRow (GCodeSpeedSelector).
.grayOutOfScopeRow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.7);
  cursor: pointer;
  user-select: none;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
  }
}

.gradientEmpty {
  margin: 0;
  text-align: center;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.4);
}

