// Légende « Type de ligne » : même vocabulaire visuel que GCodeSpeedSelector (libellés 11px/600
// blancs translucides, cyan pour l'état actif) dans le verre du panneau du haut de Prévisualisation.
.root {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 12px 8px 10px 12px;
}

// En-tête et lignes partagent la même grille ; `scrollbar-gutter` réserve la même largeur de barre
// de défilement des deux côtés pour garder les colonnes alignées.
.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 62px 48px 46px 16px;
  column-gap: 5px;
  align-items: center;
  padding: 0 6px;
}

.header {
  flex: 0 0 auto;
  height: 26px;
  overflow-y: hidden;
  scrollbar-gutter: stable;
  font-size: 10px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.rows {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.row {
  height: 22px;
  border-radius: 6px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.06);
  }
}

.name {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.swatch {
  flex: 0 0 10px;
  height: 10px;
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.numeric {
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.row .numeric {
  font-size: 10.5px;
  color: rgba(255, 255, 255, 0.7);
}

.row .dash {
  color: rgba(255, 255, 255, 0.25);
}

// Type masqué dans le viewport : ligne atténuée, case restant pleinement lisible.
.off {
  .name,
  .numeric {
    opacity: 0.4;
  }
}

.checkbox {
  appearance: none;
  justify-self: end;
  width: 16px;
  height: 16px;
  margin: 0;
  border-radius: 5px;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  cursor: pointer;
  position: relative;
  transition: all 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.14);
  }

  &:checked {
    background: rgba(0, 240, 255, 0.18);
    box-shadow: 0 0 8px rgba(0, 240, 255, 0.25);

    &::after {
      content: '';
      position: absolute;
      left: 5px;
      top: 2px;
      width: 4px;
      height: 9px;
      border: solid #00f0ff;
      border-width: 0 1px 1px 0;
      transform: rotate(45deg);
    }
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

// --- Sélecteur « Colorer par » (GCodeColorBySelector) ------------------------------------------

// Déclencheur du sélecteur « colorer par » : le libellé de l'en-tête de colonne LUI-MÊME (« Type de
// ligne », ou le nom du mode actif), pas un bandeau séparé — cadre visible seulement au survol,
// chevron toujours accolé pour signaler qu'il ouvre un menu.
.colorByTrigger {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  margin: 0 -6px 0 -2px;
  padding: 0 6px 0 2px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition: background-color 0.15s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.18);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.colorByChevron {
  flex: 0 0 auto;
  opacity: 0.7;
}

// Popover : même design que les menus de catégorie de CategoriesSidebar.module.scss
// (.fusionMenuContainer/.itemRow/.sectionTitle/.externalScrollThumb), recopié fidèlement ici plutôt
// que partagé entre modules CSS (couplage fragile) — verre sombre + flou, cartes de ligne, curseur
// de défilement externe glissable. Rendu dans un Portal (document.body, hors du panneau et de son
// `isolation: isolate`) : son z-index doit donc dépasser celui du panneau le plus élevé de
// CategoriesSidebar (1003), sans quoi il s'affiche derrière lui.
.colorByMenu {
  // !important : neutralise les classes Tailwind du composant shadcn par défaut (même spécificité,
  // ordre d'injection CSS non garanti entre Tailwind et les modules SCSS) — z-index, et fond/flou
  // posés directement ici (pas sur un ::before enfant) : Radix enveloppe ce Content dans un wrapper
  // à `transform` pour le positionner, et un `backdrop-filter` ne floute que ce qui est peint DANS
  // le même sous-arbre transformé — un ::before enfant de ce même élément n'a donc rien de réel à
  // flouter derrière lui (d'où le fond gris plat observé) ; posé sur l'élément transformé lui-même,
  // il capture correctement ce qu'il y a derrière LUI dans la page.
  // !important sur TOUTE cette règle : le composant shadcn par défaut porte déjà des classes
  // Tailwind (z-50, bg-popover, p-4, border, rounded-md, shadow-md...) de même spécificité que
  // cette classe module — l'ordre d'injection CSS entre Tailwind et les modules SCSS n'est pas
  // garanti, donc SANS !important certaines de ces propriétés s'affichaient (z-index, fond, ombre
  // déjà rencontrés un par un) et d'autres non selon l'ordre du jour, silencieusement. Plus fiable
  // de neutraliser tout le lot d'un coup que de découvrir chaque propriété écrasée au cas par cas.
  z-index: 1100 !important;
  position: relative !important;
  background: rgba(10, 15, 26, 0.65) !important;
  // Même intensité que Sidebar.module.scss (.toolbar) — 16px était trop prononcé pour ce menu.
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  width: 260px !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 16px !important;
  overflow: visible !important;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3) !important;
}

.colorByMenuContent {
  max-height: 320px;
  overflow-y: scroll;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-radius: inherit;
  color: rgba(255, 255, 255, 0.85);

  &::-webkit-scrollbar {
    width: 0;
    background: transparent;
  }
}

// Même piste que .externalScrollThumb (CategoriesSidebar.module.scss) : hors du conteneur
// scrollable, posée à droite du menu, glissable (cf. useExternalScrollThumb).
.externalScrollThumb {
  position: absolute;
  left: calc(100% + 4px);
  width: 6px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-radius: 999px;
  pointer-events: auto;
  cursor: default;
  z-index: 1;
  transition: width 0.25s cubic-bezier(0.16, 1, 0.3, 1), background 0.2s ease;

  &:hover,
  &.dragging {
    width: 12px;
    background: rgba(255, 255, 255, 0.35);
  }
}

.sectionGroup {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sectionTitle {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.5px;
}

.itemsList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.itemRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.9);
  cursor: pointer;
  outline: none;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  transform: perspective(400px) translateZ(0px);

  &:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 255, 255, 0.2);
    transform: perspective(400px) translateZ(6px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  }

  &:focus-visible {
    box-shadow: 0 0 0 1px rgba(0, 240, 255, 0.6);
  }
}

.activeItemRow {
  background: rgba(0, 240, 255, 0.14);
  border-color: rgba(0, 240, 255, 0.3);
  color: #00f0ff;
}

.itemName {
  flex: 1;
  padding-right: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}

.colorByItemSwatch {
  flex: 0 0 20px;
  height: 6px;
  border-radius: 3px;
}

