167	  const span = fileRange.max - fileRange.min;
168	  return span > 1e-9 ? (value - fileRange.min) / span : 0.5;
169	};
170	
171	/**
172	 * Barre de dégradé verticale + curseur double (min/max) + case « hors-portée en gris » : resserrer
173	 * les poignées RECADRE toute la rampe sur l'intervalle choisi (les valeurs qu'il contient s'étalent
174	 * sur tout le dégradé bleu→rouge), ce que la barre elle-même représente déjà en totalité — seules
175	 * les poignées se déplacent le long d'elle, positionnées par fraction des bornes RÉELLES du fichier
176	 * (`fileRange`), pour indiquer où se situe la portée choisie dans l'étendue complète des valeurs.
177	 */
178	const GCodeGradientScale: React.FC<GCodeGradientScaleProps> = ({ mode, fileRange, scope, setScope }) => {
179	  const trackRef = React.useRef<HTMLDivElement>(null);
180	  const [dragging, setDragging] = React.useState<'min' | 'max' | null>(null);
181	
182	  // Poignées positionnées de BAS en HAUT (min en bas, max en haut — sens de VERTICAL_GRADIENT_CSS),
183	  // donc `bottom: fraction * 100%` plutôt que `top`.
184	  const minFraction = fractionOf(scope.min, fileRange);
185	  const maxFraction = fractionOf(scope.max, fileRange);
