188	    const track = trackRef.current;
189	    if (!track) return;
190	    const rect = track.getBoundingClientRect();
191	    const fraction = rect.height > 0 ? 1 - Math.max(0, Math.min(1, (clientY - rect.top) / rect.height)) : 0;
