/** Fraction [0,1] de `value` dans `fileRange`, pour positionner une poignée le long de la barre. */
const fractionOf = (value: number, fileRange: ColorByRange) => {
  const span = fileRange.max - fileRange.min;
  return span > 1e-9 ? (value - fileRange.min) / span : 0.5;
};

// Crans du curseur de portée : incrément de base 1 unité (1 mm/s, 1°C, 1%...), qui se réduit d'un
// facteur 10 à chaque dixième de la plage restant en se rapprochant de la borne minimale du
// fichier (le « bord petit ») — permet un réglage fin de valeurs proches de zéro/du bas de
// l'échelle (ex. hauteur de couche en mm) sans perdre les crans grossiers, lisibles au glisser,
// sur le reste de la plage. Deux effets recherchés : (1) plus de précision là où les petites
// valeurs comptent le plus, (2) moins de valeurs distinctes possibles → moins de recalculs du
// tampon de couleurs par sommet pendant le glisser (cf. GCodeGradientScale), qui masque le lag
// observé en rendant le mouvement du curseur volontairement saccadé plutôt que trahir la latence
// d'un recalcul continu.
const RANGE_HANDLE_BASE_STEP = 1;
const snapRangeValue = (value: number, fileRange: ColorByRange) => {
  const span = fileRange.max - fileRange.min;
  if (!(span > 1e-9)) return value;
  const distFromMin = value - fileRange.min;
  // Combien de dixièmes de la plage séparent `value` du bas de l'échelle (0 = collé au minimum).
  const tenths = Math.floor((distFromMin / span) * 10);
  const step = RANGE_HANDLE_BASE_STEP / Math.pow(10, Math.max(0, 9 - tenths));
  const snapped = fileRange.min + Math.round(distFromMin / step) * step;
  return Math.max(fileRange.min, Math.min(fileRange.max, snapped));
};

