294	  const convert = async (mode: ConversionMode, dropOffPlate: boolean) => {
295	    const source = sourceRef.current;
296	    if (!source || conversion.status === 'running') return;
297	    setOffPlateHighlight(false);
298	    setConversion({ status: 'running', progress: 0, mode, error: null });
299	    try {
300	      const { text, summary } = await runConversion(
301	        {
302	          text: source.text,
303	          mode,
304	          centerX: source.parsed.bedCenter.x,
305	          centerY: source.parsed.bedCenter.y,
306	          source: source.parsed.generator?.name ?? source.name,
307	          dropOutsideRadius: dropOffPlate ? PLATE_RADIUS_MM : 0,
308	        },
309	        (progress) => setConversion((prev) => (prev.status === 'running' ? { ...prev, progress } : prev)),
310	      );
311	      const name = `${source.name.replace(/\.[^.]+$/, '')}_apex${mode === 'dynamic' ? '_dynamique' : ''}.gcode`;
312	      if (!loadText(text, name)) throw new Error('Le G-code converti est illisible.');
313	      setConversion({ status: 'done', progress: 100, mode, error: null });
314	      const detail = summary
315	        ? ` (écart max ${summary.maxErrorMm.toFixed(3).replace('.', ',')} mm${mode === 'dynamic' ? `, B de ${summary.bMin.toFixed(0)}° à ${summary.bMax.toFixed(0)}°` : ''}${summary.droppedMoves ? `, ${summary.droppedMoves} mouvements hors plateau supprimés` : ''})`
