setOffPlateHighlight(show) {
  highlightOffPlate = show;
  applyVisibility();
},
setOffPlateBlinking(blinking) {
  blinkingOffPlate = blinking;
  if (blinking && !offPlateBlinkObserver) {
    offPlateBlinkObserver = scene.onBeforeRenderObservable.add(() => {
      // Pulsation sinusoïdale de l'émissivité, jamais complètement éteinte (garde le trait
      // lisible en rouge en permanence, cf. demande : « les laisser en rouge... mais les faire
      // clignoter » — pas un vrai on/off qui les ferait disparaître un instant).
      const t = (performance.now() / 1000 / OFF_PLATE_BLINK_PERIOD_S) * 2 * Math.PI;
      const pulse = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(t));
      offPlateMat.emissiveColor.copyFrom(OFF_PLATE_EMISSIVE).scaleInPlace(pulse);
    });
  } else if (!blinking && offPlateBlinkObserver) {
    scene.onBeforeRenderObservable.remove(offPlateBlinkObserver);
    offPlateBlinkObserver = null;
    offPlateMat.emissiveColor.copyFrom(OFF_PLATE_EMISSIVE);
  }

