      // instant), à OFF_PLATE_BLINK_PERIOD_S par cycle complet. Interpolation lissée (cosinus,
      // 0→1→0) plutôt qu'un saut net entre les deux couleurs.
      const t = (performance.now() / 1000 / OFF_PLATE_BLINK_PERIOD_S) * 2 * Math.PI;
      const f = 0.5 - 0.5 * Math.cos(t);
      BABYLON.Color3.LerpToRef(OFF_PLATE_EMISSIVE, OFF_PLATE_BLINK_EMISSIVE, f, offPlateMat.emissiveColor);
    });
  } else if (!blinking && offPlateBlinkObserver) {
    scene.onBeforeRenderObservable.remove(offPlateBlinkObserver);
    offPlateBlinkObserver = null;
    offPlateMat.emissiveColor.copyFrom(OFF_PLATE_EMISSIVE);
  }
},

